  DBMS_OUTPUT.PUT_LINE(q'~    if (fam.perContainer) m.ctr = conKind(f.dbid, f.con);~');
  DBMS_OUTPUT.PUT_LINE(q'~    if (fam.id === 'host-cpu') m.ctr = 'host';~');
  DBMS_OUTPUT.PUT_LINE(q'~    m.sev = worstSev(alerts.map(function (a) { return a.sev; }).concat([f.sev]));~');
  DBMS_OUTPUT.PUT_LINE(q'~    m.unit = unitFor(f.u, Math.max(Math.abs(f.v || 0), Math.abs(f.lim || 0)));~');
  DBMS_OUTPUT.PUT_LINE(q'~    m.facts = fam.facts(m);~');
  DBMS_OUTPUT.PUT_LINE(q'~    alerts.forEach(function (a) {~');
  DBMS_OUTPUT.PUT_LINE(q'~      var fk = ALERT_FACT[a.kind], tone = a.sev === 'CRIT' ? 'crit' : a.sev === 'WARN' ? 'warn' : null;~');
  DBMS_OUTPUT.PUT_LINE(q'~      m.facts.forEach(function (x) {~');
  DBMS_OUTPUT.PUT_LINE(q'~        if (fk && x.k === fk && tone && (x.tone !== 'crit')) x.tone = tone;~');
  DBMS_OUTPUT.PUT_LINE(q'~      });~');
  DBMS_OUTPUT.PUT_LINE(q'~    });~');
  DBMS_OUTPUT.PUT_LINE(q'~    m.order = [SEV_RANK[m.sev], f.dtf == null ? 1e9 : f.dtf, -(f.pct || 0)];~');
  DBMS_OUTPUT.PUT_LINE(q'~    return m;~');
  DBMS_OUTPUT.PUT_LINE(q'~  }~');
  DBMS_OUTPUT.PUT_LINE(NULL);
  DBMS_OUTPUT.PUT_LINE(q'~  /* ---------- facts per family ---------- */~');
  DBMS_OUTPUT.PUT_LINE(NULL);
  DBMS_OUTPUT.PUT_LINE(q'~  function dtfFact(f, label) {~');
  DBMS_OUTPUT.PUT_LINE(q'~    var tone = '';~');
  DBMS_OUTPUT.PUT_LINE(q'~    if (f.dtf != null && f.q === 'OK') tone = f.dtf <= K.dtfCrit ? 'crit' : f.dtf <= K.dtfWarn ? 'warn' : '';~');
  DBMS_OUTPUT.PUT_LINE(q'~    var sub = '';~');
  DBMS_OUTPUT.PUT_LINE(q'~    if (f.dtf != null) {~');
  DBMS_OUTPUT.PUT_LINE(q'~      if (f.dtf > 3650) return { k: 'dtf', l: label, v: fDays(f.dtf), s: 'not in sight', tone: 'muted' };~');
  DBMS_OUTPUT.PUT_LINE(q'~      sub = '\u2192 ' + fDay(LAST + f.dtf) + (f.dtfLo != null && f.dtfHi != null && Math.round(f.dtfLo) !== Math.round(f.dtfHi)~');
  DBMS_OUTPUT.PUT_LINE(q'~        ? ' \u00b7 ' + Math.round(f.dtfLo) + '\u2013' + Math.round(f.dtfHi) + ' d' : '');~');
  DBMS_OUTPUT.PUT_LINE(q'~    } else if (f.q === 'FLAT') sub = f.rst === 'STOP' ? 'growth stopped' : 'no growth';~');
  DBMS_OUTPUT.PUT_LINE(q'~    else if (f.q === 'CYCLIC') sub = 'peaks not growing';~');
  DBMS_OUTPUT.PUT_LINE(q'~    else if (f.slope != null && f.slope <= 0) sub = 'not growing';~');
  DBMS_OUTPUT.PUT_LINE(q'~    else sub = 'beyond the forecast';~');
  DBMS_OUTPUT.PUT_LINE(q'~    return { k: 'dtf', l: label, v: f.dtf != null ? fDays(f.dtf) : '\u2013', s: sub, tone: f.dtf == null ? 'muted' : tone };~');
  DBMS_OUTPUT.PUT_LINE(q'~  }~');
  DBMS_OUTPUT.PUT_LINE(NULL);
  DBMS_OUTPUT.PUT_LINE(q'~  function stamp(d) { return '<span class="stamp">\u2192 ' + fDay(Math.round(d)) + '</span>'; }~');
  DBMS_OUTPUT.PUT_LINE(NULL);
  DBMS_OUTPUT.PUT_LINE(q'~  function pctTone(p, warn, crit) { return p == null ? '' : p >= crit ? 'crit' : p >= warn ? 'warn' : ''; }~');
  DBMS_OUTPUT.PUT_LINE(NULL);
  DBMS_OUTPUT.PUT_LINE(q'~  // Why the fit window is shorter than the history (CAPR_FIT.restart_reason).~');
  DBMS_OUTPUT.PUT_LINE(q'~  var RESTART = { PURGE: 'since the purge', STOP: 'since growth stopped', START: 'since growth began' };~');
  DBMS_OUTPUT.PUT_LINE(NULL);
  DBMS_OUTPUT.PUT_LINE(q'~  function tbspcFacts(m) {~');
  DBMS_OUTPUT.PUT_LINE(q'~    var f = m.f, out = [];~');
  DBMS_OUTPUT.PUT_LINE(q'~    var since = f.rst && RESTART[f.rst] ? ' ' + RESTART[f.rst] + (f.rstDay ? ', ' + fDay(dayN(f.rstDay)) : '') : '';~');
  DBMS_OUTPUT.PUT_LINE(q'~    out.push({ k: 'pct', l: 'Used', v: num(f.pct, 1) + '<small>%</small>', s: m.unit.fmt(f.v) + ' of ' + m.unit.fmt(f.lim),~');
  DBMS_OUTPUT.PUT_LINE(q'~      tone: pctTone(f.pct, K.nfWarn, K.nfCrit) });~');
  DBMS_OUTPUT.PUT_LINE(q'~    if (f.q === 'CYCLIC') {~');
  DBMS_OUTPUT.PUT_LINE(q'~      out.push({ l: 'Cycle peak', v: num(f.cycPk, 1) + '<small>%</small>', s: (f.cycN || 0) + ' purges, every ' + Math.round(f.cycD || 0) + ' d' });~');
  DBMS_OUTPUT.PUT_LINE(q'~      out.push({ l: 'Peak growth', v: m.unit.rate(f.pkSlope) });~');
  DBMS_OUTPUT.PUT_LINE(q'~    } else {~');
  DBMS_OUTPUT.PUT_LINE(q'~      out.push({ l: 'Growth', v: m.unit.rate(f.slope), s: f.accel != null && f.accel >= 1.5 ? 'accelerating \u00d7' + num(f.accel, 1) : 'fit over ' + (f.n || '\u2013') + ' d' + since });~');
  DBMS_OUTPUT.PUT_LINE(q'~    }~');
  DBMS_OUTPUT.PUT_LINE(q'~    out.push(dtfFact(f, 'Full in'));~');
  DBMS_OUTPUT.PUT_LINE(q'~    // The disk the tablespaces share stops it before its own limit (CAPR_FIT.dtf_shared).~');
  DBMS_OUTPUT.PUT_LINE(q'~    if (f.dtfSh != null && (f.dtf == null || f.dtfSh < f.dtf))~');
  DBMS_OUTPUT.PUT_LINE(q'~      out.push({ l: 'On the shared disk', v: fDays(f.dtfSh), s: 'stuck at ' + num(f.limSh, 1) + ' GiB' + (f.disk ? ', disk ' + esc(f.disk) : '') });~');
  DBMS_OUTPUT.PUT_LINE(q'~    if (f.need90 > 0) out.push({ l: 'Add for 90 d', v: num(f.need90, 1) + '<small>GiB</small>', s: f.addBy ? 'by ' + fDay(dayN(f.addBy)) : '' });~');
  DBMS_OUTPUT.PUT_LINE(q'~    if (f.below) out.push({ l: 'Limit', v: 'below used', tone: 'crit' });~');
  DBMS_OUTPUT.PUT_LINE(q'~    return out;~');
  DBMS_OUTPUT.PUT_LINE(q'~  }~');
  DBMS_OUTPUT.PUT_LINE(NULL);
  DBMS_OUTPUT.PUT_LINE(q'~  function limitFacts(label, limWord) {~');
  DBMS_OUTPUT.PUT_LINE(q'~    return function (m) {~');
  DBMS_OUTPUT.PUT_LINE(q'~      var f = m.f, out = [];~');
  DBMS_OUTPUT.PUT_LINE(q'~      out.push({ l: label, v: m.unit.fmt(f.v), s: f.lim != null ? 'of ' + m.unit.fmt(f.lim) + ' ' + limWord : 'no limit' });~');
  DBMS_OUTPUT.PUT_LINE(q'~      if (f.pct != null) out.push({ k: 'pct', l: 'Of ' + limWord, v: num(f.pct, 1) + '<small>%</small>', tone: pctTone(f.pct, SERIES_SAT, 100) });~');
  DBMS_OUTPUT.PUT_LINE(q'~      out.push({ l: m.unit.rateLabel, v: m.unit.rate(f.slope), s: 'fit over ' + (f.n || '\u2013') + ' d' });~');
  DBMS_OUTPUT.PUT_LINE(q'~      if (f.lim != null) out.push(dtfFact(f, SERIES_SAT + '% in'));~');
  DBMS_OUTPUT.PUT_LINE(q'~      return out;~');
  DBMS_OUTPUT.PUT_LINE(q'~    };~');
  DBMS_OUTPUT.PUT_LINE(q'~  }~');
  DBMS_OUTPUT.PUT_LINE(NULL);
  DBMS_OUTPUT.PUT_LINE(q'~  /* A flow has no limit (redo per day, the I/O rates): the latest day, the~');
  DBMS_OUTPUT.PUT_LINE(q'~     week's average and the trend. fam.flow words the latest day. */~');
  DBMS_OUTPUT.PUT_LINE(q'~  function flowFacts(label) {~');
  DBMS_OUTPUT.PUT_LINE(q'~    return function (m) {~');
  DBMS_OUTPUT.PUT_LINE(q'~      var f = m.f;~');
  DBMS_OUTPUT.PUT_LINE(q'~      var avg = avgLast(m.pts, 7);~');
  DBMS_OUTPUT.PUT_LINE(q'~      return [~');
  DBMS_OUTPUT.PUT_LINE(q'~        { l: label, v: m.unit.fmt(lastVal(m.pts)) },~');
  DBMS_OUTPUT.PUT_LINE(q'~        { l: '7-day average', v: m.unit.fmt(avg) },~');
  DBMS_OUTPUT.PUT_LINE(q'~        { l: m.unit.rateLabel, v: m.unit.rate(f.slope), s: 'fit over ' + (f.n || '\u2013') + ' d' }~');
  DBMS_OUTPUT.PUT_LINE(q'~      ];~');
  DBMS_OUTPUT.PUT_LINE(q'~    };~');
  DBMS_OUTPUT.PUT_LINE(q'~  }~');
  DBMS_OUTPUT.PUT_LINE(NULL);
  DBMS_OUTPUT.PUT_LINE(q'~  function cpuFacts(m, p95, avg) {~');
  DBMS_OUTPUT.PUT_LINE(q'~    var f = m.f, out = [];~');
  DBMS_OUTPUT.PUT_LINE(q'~    out.push({ k: 'now', l: 'Busy-hour p95', v: num(f.v, 1) + '<small>%</small>', s: f.hot ? 'at the ' + CPU_SAT + '% line now' : 'of ' + p95,~');
  DBMS_OUTPUT.PUT_LINE(q'~      tone: pctTone(f.v, CPU_SAT * 0.9, CPU_SAT) });~');
  DBMS_OUTPUT.PUT_LINE(q'~    var a = m.fits[avg];~');
  DBMS_OUTPUT.PUT_LINE(q'~    out.push({ l: 'Daily average', v: a ? num(a.v, 1) + '<small>%</small>' : '\u2013' });~');
  DBMS_OUTPUT.PUT_LINE(q'~    out.push({ l: m.unit.rateLabel, v: m.unit.rate(f.slope), s: f.sig === 0 ? 'not significant' : 'fit over ' + (f.n || '\u2013') + ' d' });~');
  DBMS_OUTPUT.PUT_LINE(q'~    out.push(dtfFact(f, CPU_SAT + '% in'));~');
  DBMS_OUTPUT.PUT_LINE(q'~    return out;~');
  DBMS_OUTPUT.PUT_LINE(q'~  }~');
  DBMS_OUTPUT.PUT_LINE(q'~  function hostCpuFacts(m) {~');
  DBMS_OUTPUT.PUT_LINE(q'~    var out = cpuFacts(m, 'host CPU', 'BUSY_PCT');~');
  DBMS_OUTPUT.PUT_LINE(q'~    var pk = m.fits.BUSY_PEAK;~');
  DBMS_OUTPUT.PUT_LINE(q'~    if (pk) out.splice(2, 0, { l: 'Peak window', v: num(pk.v, 1) + '<small>%</small>', s: 'business hours' });~');
  DBMS_OUTPUT.PUT_LINE(q'~    return out;~');
  DBMS_OUTPUT.PUT_LINE(q'~  }~');
  DBMS_OUTPUT.PUT_LINE(q'~  function dbCpuFacts(m) { return cpuFacts(m, 'host CPUs', 'DB_CPU_PCT'); }~');
  DBMS_OUTPUT.PUT_LINE(NULL);
  DBMS_OUTPUT.PUT_LINE(q'~  function lastVal(pts) { for (var i = pts.length - 1; i >= 0; i--) if (pts[i].y != null) return pts[i].y; return null; }~');
  DBMS_OUTPUT.PUT_LINE(q'~  function avgLast(pts, n) {~');
  DBMS_OUTPUT.PUT_LINE(q'~    var s = 0, c = 0;~');
  DBMS_OUTPUT.PUT_LINE(q'~    pts.forEach(function (p) { if (p.y != null && p.x > LAST - n) { s += p.y; c++; } });~');
  DBMS_OUTPUT.PUT_LINE(q'~    return c ? s / c : null;~');
  DBMS_OUTPUT.PUT_LINE(q'~  }~');
  DBMS_OUTPUT.PUT_LINE(NULL);
  DBMS_OUTPUT.PUT_LINE(q'~  /* ---------- alert and anomaly wording (facts only) ---------- */~');
  DBMS_OUTPUT.PUT_LINE(NULL);
  DBMS_OUTPUT.PUT_LINE(q'~  function alertWhen(a) {~');
  DBMS_OUTPUT.PUT_LINE(q'~    if (a.unit === 'DAYS' || a.u === 'DAYS') return stamp(LAST + a.v);~');
  DBMS_OUTPUT.PUT_LINE(q'~    if (/_ANOM$/.test(a.kind)) return '<span class="when">' + fDay(dayN(a.n > 1 ? a.first : a.day)) + (a.n > 1 ? '\u2013' + fDay(dayN(a.day)) : '') + '</span>';~');
  DBMS_OUTPUT.PUT_LINE(q'~    return '<span class="when">now</span>';~');
  DBMS_OUTPUT.PUT_LINE(q'~  }~');
  DBMS_OUTPUT.PUT_LINE(NULL);
  DBMS_OUTPUT.PUT_LINE(q'~  function alertFact(a, m) {~');
  DBMS_OUTPUT.PUT_LINE(q'~    var u = m ? m.unit : unitFor(a.u);~');
  DBMS_OUTPUT.PUT_LINE(q'~    switch (a.kind) {~');
  DBMS_OUTPUT.PUT_LINE(q'~      case 'TBSPC_FULL': return 'full in <b>' + fDays(a.v) + '</b>';~');
  DBMS_OUTPUT.PUT_LINE(q'~      case 'DISK_FULL': return 'shared disk full in <b>' + fDays(a.v) + '</b>';~');
  DBMS_OUTPUT.PUT_LINE(q'~      case 'CPU_SAT': case 'DBCPU_SAT': return CPU_SAT + '% busy in <b>' + fDays(a.v) + '</b>';~');
  DBMS_OUTPUT.PUT_LINE(q'~      case 'SERIES_LIMIT': return SERIES_SAT + '% of limit in <b>' + fDays(a.v) + '</b>';~');
  DBMS_OUTPUT.PUT_LINE(q'~      case 'TBSPC_NEARFULL': return '<b>' + num(a.v, 1) + '%</b> used';~');
  DBMS_OUTPUT.PUT_LINE(q'~      case 'SERIES_NEARLIMIT': return '<b>' + num(a.v, 1) + '%</b> of limit';~');
  DBMS_OUTPUT.PUT_LINE(q'~      case 'CPU_HOT': case 'DBCPU_HOT': return 'busy-hour p95 <b>' + num(a.v, 1) + '%</b> now';~');
  DBMS_OUTPUT.PUT_LINE(q'~      case 'CPU_SHIFT': return 'level shift <b>' + sign(a.v) + num(Math.abs(a.v), 1) + '%</b>';~');
  DBMS_OUTPUT.PUT_LINE(q'~      case 'DATA_STALE': return 'no AWR snapshot for <b>' + auto(a.v) + ' h</b>';~');
  DBMS_OUTPUT.PUT_LINE(q'~      case 'MODEL_HEALTH': return 'ESM model ' + esc(a.msg || '');~');
  DBMS_OUTPUT.PUT_LINE(q'~      case 'TBSPC_FAMILY': return 'filling member may reach <b>' + num(a.v, 2) + ' GiB</b>, ceiling ' + num(a.thr, 2) + ' GiB';~');
  DBMS_OUTPUT.PUT_LINE(q'~    }~');
  DBMS_OUTPUT.PUT_LINE(q'~    if (/_ANOM$/.test(a.kind)) {~');
  DBMS_OUTPUT.PUT_LINE(q'~      var v = a.u === 'BYTES' ? fBytes(a.v) + '/d' : a.u === 'PCT' ? num(a.v, 1) + '%' : a.u === 'GIB' ? auto(a.v) + ' GiB/d' : auto(a.v);~');
  DBMS_OUTPUT.PUT_LINE(q'~      var t = a.u === 'BYTES' ? fBytes(a.thr) + '/d' : a.u === 'PCT' ? num(a.thr, 1) + '%' : a.u === 'GIB' ? auto(a.thr) + ' GiB/d' : auto(a.thr);~');
  DBMS_OUTPUT.PUT_LINE(q'~      var span = a.n > 1 ? ' \u00b7 ' + a.n + ' days' : '';~');
  DBMS_OUTPUT.PUT_LINE(q'~      return 'unusual <b>' + v + '</b>, normal \u2264 ' + t + (a.maxz != null ? ' \u00b7 z ' + num(a.maxz, 1) : '') + span;~');
  DBMS_OUTPUT.PUT_LINE(q'~    }~');
  DBMS_OUTPUT.PUT_LINE(q'~    return esc(a.msg || a.kind);~');
  DBMS_OUTPUT.PUT_LINE(q'~  }~');
  DBMS_OUTPUT.PUT_LINE(NULL);
  DBMS_OUTPUT.PUT_LINE(q'~  /* One chip per flagged day: the day verdict (worst mode) plus its flagged hours. */~');
  DBMS_OUTPUT.PUT_LINE(q'~  function anomalyEvents(m) {~');
  DBMS_OUTPUT.PUT_LINE(q'~    var days = {};~');
  DBMS_OUTPUT.PUT_LINE(q'~    m.anoms.forEach(function (a) {~');
  DBMS_OUTPUT.PUT_LINE(q'~      if (a.ak === 'CPU_SHIFT') return;~');
  DBMS_OUTPUT.PUT_LINE(q'~      var d = dayN(a.ts);~');
  DBMS_OUTPUT.PUT_LINE(q'~      if (d <= LAST - ANOM_DAYS) return;~');
  DBMS_OUTPUT.PUT_LINE(q'~      var e = days[d] || (days[d] = { d: d, day: null, hours: {}, nh: 0, f: a.f, z: 0 });~');
  DBMS_OUTPUT.PUT_LINE(q'~      if (a.grain === 'HOUR') {~');
  DBMS_OUTPUT.PUT_LINE(q'~        if (!e.hours[a.ts]) e.nh++;~');
  DBMS_OUTPUT.PUT_LINE(q'~        e.hours[a.ts] = a.f;~');
  DBMS_OUTPUT.PUT_LINE(q'~      } else if (!e.day || Math.abs(a.z) > Math.abs(e.day.z)) e.day = a;~');
  DBMS_OUTPUT.PUT_LINE(q'~      if (Math.abs(a.z || 0) >= Math.abs(e.z)) { e.z = a.z; e.f = a.f; }~');
  DBMS_OUTPUT.PUT_LINE(q'~    });~');
  DBMS_OUTPUT.PUT_LINE(q'~    return Object.keys(days).map(function (k) { return days[k]; })~');
  DBMS_OUTPUT.PUT_LINE(q'~      .sort(function (a, b) { return b.d - a.d; });~');
  DBMS_OUTPUT.PUT_LINE(q'~  }~');
  DBMS_OUTPUT.PUT_LINE(NULL);
  DBMS_OUTPUT.PUT_LINE(q'~  function anomalyChip(ev, m) {~');
  DBMS_OUTPUT.PUT_LINE(q'~    var val = '', usual = '', a = ev.day;~');
  DBMS_OUTPUT.PUT_LINE(q'~    if (a) {~');
  DBMS_OUTPUT.PUT_LINE(q'~      if (m.fam.id === 'tablespaces' || m.f.s === 'DB_SIZE_GB') {~');
  DBMS_OUTPUT.PUT_LINE(q'~        var scale = m.fam.id === 'tablespaces' ? 1 : Math.pow(1024, 3);~');
  DBMS_OUTPUT.PUT_LINE(q'~        val = sign(a.v) + fBytes(Math.abs(a.v * scale)) + ' in a day';~');
  DBMS_OUTPUT.PUT_LINE(q'~        usual = 'usual ' + fBytes(a.e * scale);~');
  DBMS_OUTPUT.PUT_LINE(q'~      } else {~');
  DBMS_OUTPUT.PUT_LINE(q'~        val = m.unit.fmt(a.v);~');
  DBMS_OUTPUT.PUT_LINE(q'~        usual = 'usual ' + m.unit.fmt(a.e);~');
  DBMS_OUTPUT.PUT_LINE(q'~      }~');
  DBMS_OUTPUT.PUT_LINE(q'~    }~');
END;
/
BEGIN
  DBMS_OUTPUT.PUT_LINE(q'~    if (ev.nh) {~');
  DBMS_OUTPUT.PUT_LINE(q'~      var hrs = ev.nh + ' h ' + (ev.f === 'LOW' ? 'below' : 'above') + ' their usual hour';~');
  DBMS_OUTPUT.PUT_LINE(q'~      if (val) usual += ' \u00b7 ' + hrs; else val = hrs;~');
  DBMS_OUTPUT.PUT_LINE(q'~    }~');
  DBMS_OUTPUT.PUT_LINE(q'~    return '<div class="an ' + (ev.f === 'LOW' ? 'lo' : 'hi') + '"><span class="dt">' + fWDay(ev.d) + '</span><span class="vv">' + val +~');
  DBMS_OUTPUT.PUT_LINE(q'~      '</span><span class="us">' + usual + '</span><span class="z">z ' + num(ev.z, 1) + '</span></div>';~');
  DBMS_OUTPUT.PUT_LINE(q'~  }~');
  DBMS_OUTPUT.PUT_LINE(NULL);
  DBMS_OUTPUT.PUT_LINE(q'~  /* ---------- charts ---------- */~');
  DBMS_OUTPUT.PUT_LINE(NULL);
  DBMS_OUTPUT.PUT_LINE(q'~  var CHARTS = [];~');
  DBMS_OUTPUT.PUT_LINE(q'~  var W = 640, H = 196, ML = 44, MR = 14, MT = 22, MB = 24;~');
  DBMS_OUTPUT.PUT_LINE(NULL);
  DBMS_OUTPUT.PUT_LINE(q'~  function niceTicks(lo, hi, n) {~');
  DBMS_OUTPUT.PUT_LINE(q'~    var span = hi - lo || 1, step = Math.pow(10, Math.floor(Math.log10(span / n)));~');
  DBMS_OUTPUT.PUT_LINE(q'~    var err = span / n / step;~');
  DBMS_OUTPUT.PUT_LINE(q'~    step *= err >= 7.5 ? 10 : err >= 3.5 ? 5 : err >= 1.5 ? 2 : 1;~');
  DBMS_OUTPUT.PUT_LINE(q'~    var t = [], v = Math.ceil(lo / step) * step;~');
  DBMS_OUTPUT.PUT_LINE(q'~    for (; v <= hi + step * 1e-9; v += step) t.push(+v.toFixed(10));~');
  DBMS_OUTPUT.PUT_LINE(q'~    var dp = Math.max(0, -Math.floor(Math.log10(step) + 1e-9));~');
  DBMS_OUTPUT.PUT_LINE(q'~    return { ticks: t, step: step, dp: dp };~');
  DBMS_OUTPUT.PUT_LINE(q'~  }~');
  DBMS_OUTPUT.PUT_LINE(NULL);
  DBMS_OUTPUT.PUT_LINE(q'~  function forecastKnots(m, method) {~');
  DBMS_OUTPUT.PUT_LINE(q'~    return m.fc.filter(function (r) { return r.m === method; })~');
  DBMS_OUTPUT.PUT_LINE(q'~      .map(function (r) { return { x: dayN(r.t), y: r.v, lo: r.lo, hi: r.hi }; })~');
  DBMS_OUTPUT.PUT_LINE(q'~      .sort(function (a, b) { return a.x - b.x; });~');
  DBMS_OUTPUT.PUT_LINE(q'~  }~');
  DBMS_OUTPUT.PUT_LINE(NULL);
  DBMS_OUTPUT.PUT_LINE(q'~  function horizon(m) {~');
  DBMS_OUTPUT.PUT_LINE(q'~    var f = m.f, h = 90;~');
  DBMS_OUTPUT.PUT_LINE(q'~    var reach = m.fc.reduce(function (r, k) { return k.m === 'REGR' ? Math.max(r, k.h) : r; }, 30);~');
  DBMS_OUTPUT.PUT_LINE(q'~    if (f.dtf != null && f.dtf > 60 && f.dtf <= 330) h = Math.ceil((f.dtf + 20) / 30) * 30;~');
  DBMS_OUTPUT.PUT_LINE(q'~    return Math.min(h, reach);~');
  DBMS_OUTPUT.PUT_LINE(q'~  }~');
  DBMS_OUTPUT.PUT_LINE(NULL);
  DBMS_OUTPUT.PUT_LINE(q'~  function isHot(m) {~');
  DBMS_OUTPUT.PUT_LINE(q'~    var f = m.f;~');
  DBMS_OUTPUT.PUT_LINE(q'~    if (f.dtf != null && f.q === 'OK' && f.dtf <= K.dtfWarn) return true;~');
  DBMS_OUTPUT.PUT_LINE(q'~    if (f.k === 'TBSPC') return f.pct >= K.nfWarn;~');
  DBMS_OUTPUT.PUT_LINE(q'~    if (f.k === 'SERIES') return f.pct >= SERIES_SAT;~');
  DBMS_OUTPUT.PUT_LINE(q'~    return !!f.hot;~');
  DBMS_OUTPUT.PUT_LINE(q'~  }~');
  DBMS_OUTPUT.PUT_LINE(NULL);
  DBMS_OUTPUT.PUT_LINE(q'~  function limitLines(m) {~');
  DBMS_OUTPUT.PUT_LINE(q'~    var f = m.f, out = [];~');
  DBMS_OUTPUT.PUT_LINE(q'~    if (m.f.k === 'CPU') out.push({ y: CPU_SAT, cls: 'thr', label: CPU_SAT + '%', target: true });~');
  DBMS_OUTPUT.PUT_LINE(q'~    else if (f.lim != null) {~');
  DBMS_OUTPUT.PUT_LINE(q'~      out.push({ y: f.lim, cls: 'lim', label: 'limit ' + m.unit.fmt(f.lim), target: m.f.k === 'TBSPC' });~');
  DBMS_OUTPUT.PUT_LINE(q'~      if (m.f.k === 'SERIES') out.push({ y: f.lim * SERIES_SAT / 100, cls: 'thr', label: SERIES_SAT + '%', target: true });~');
