  DBMS_OUTPUT.PUT_LINE(q'~    }~');
  DBMS_OUTPUT.PUT_LINE(q'~    pts.forEach(function (p) {~');
  DBMS_OUTPUT.PUT_LINE(q'~      if ((p.a === 1 || p.a === -1) && p.x > LAST - ANOM_DAYS) o.push('<circle cx="' + xs(p.x).toFixed(1) + '" cy="' + ys(p.y).toFixed(1) + '" r="2" fill="' + (p.a === 1 ? 'var(--crit)' : 'var(--accent)') + '"/>');~');
  DBMS_OUTPUT.PUT_LINE(q'~    });~');
  DBMS_OUTPUT.PUT_LINE(q'~    o.push('</svg>');~');
  DBMS_OUTPUT.PUT_LINE(q'~    return o.join('');~');
  DBMS_OUTPUT.PUT_LINE(q'~  }~');
  DBMS_OUTPUT.PUT_LINE(NULL);
  DBMS_OUTPUT.PUT_LINE(q'~  /* ---------- hour heat strip (CPU) ---------- */~');
  DBMS_OUTPUT.PUT_LINE(NULL);
  DBMS_OUTPUT.PUT_LINE(q'~  function heatSvg(m) {~');
  DBMS_OUTPUT.PUT_LINE(q'~    var h = HOURS[key(m.f.dbid, m.f.con, m.fam.heat)];~');
  DBMS_OUTPUT.PUT_LINE(q'~    if (!h || !h.d.length) return '';~');
  DBMS_OUTPUT.PUT_LINE(q'~    var t0 = dayN(h.t0), rows = 14, cw = 21, rh = 13, lw = 70, top = 2;~');
  DBMS_OUTPUT.PUT_LINE(q'~    var w = lw + cw * 24, ht = top + rows * rh + 16;~');
  DBMS_OUTPUT.PUT_LINE(q'~    var grid = {};~');
  DBMS_OUTPUT.PUT_LINE(q'~    h.d.forEach(function (r) { grid[r[0] + '|' + r[1]] = r; });~');
  DBMS_OUTPUT.PUT_LINE(q'~    var o = ['<svg viewBox="0 0 ' + w + ' ' + ht + '" role="img" aria-label="hourly CPU, last 14 days">'];~');
  DBMS_OUTPUT.PUT_LINE(q'~    for (var r = 0; r < rows; r++) {~');
  DBMS_OUTPUT.PUT_LINE(q'~      var day = t0 + r, y = top + r * rh;~');
  DBMS_OUTPUT.PUT_LINE(q'~      o.push('<text x="' + (lw - 6) + '" y="' + (y + rh - 3) + '" text-anchor="end">' + fWDay(day) + '</text>');~');
  DBMS_OUTPUT.PUT_LINE(q'~      for (var c = 0; c < 24; c++) {~');
  DBMS_OUTPUT.PUT_LINE(q'~        var cell = grid[r + '|' + c], x = lw + c * cw;~');
  DBMS_OUTPUT.PUT_LINE(q'~        var fill = 'var(--heat-0)', stroke = '';~');
  DBMS_OUTPUT.PUT_LINE(q'~        if (cell && cell[2] != null) {~');
  DBMS_OUTPUT.PUT_LINE(q'~          var v = Math.max(0, Math.min(100, cell[2]));~');
  DBMS_OUTPUT.PUT_LINE(q'~          fill = 'color-mix(in oklab, var(--heat-1) ' + Math.round(v) + '%, var(--heat-0))';~');
  DBMS_OUTPUT.PUT_LINE(q'~          if (cell[3] === 1) stroke = ' stroke="var(--crit)" stroke-width="2"';~');
  DBMS_OUTPUT.PUT_LINE(q'~          if (cell[3] === -1) stroke = ' stroke="var(--accent)" stroke-width="2"';~');
  DBMS_OUTPUT.PUT_LINE(q'~        }~');
  DBMS_OUTPUT.PUT_LINE(q'~        o.push('<rect class="hc" data-d="' + day + '" data-h="' + c + '" data-v="' + (cell && cell[2] != null ? cell[2] : '') + '" data-f="' + (cell ? cell[3] : 0) + '" x="' + (x + 0.5) + '" y="' + (y + 0.5) + '" width="' + (cw - 1) + '" height="' + (rh - 1) + '" rx="1.5" fill="' + fill + '"' + stroke + '/>');~');
  DBMS_OUTPUT.PUT_LINE(q'~      }~');
  DBMS_OUTPUT.PUT_LINE(q'~    }~');
  DBMS_OUTPUT.PUT_LINE(q'~    [0, 6, 12, 18].forEach(function (hr) {~');
  DBMS_OUTPUT.PUT_LINE(q'~      o.push('<text x="' + (lw + hr * cw + cw / 2) + '" y="' + (top + rows * rh + 12) + '" text-anchor="middle">' + (hr < 10 ? '0' : '') + hr + ':00</text>');~');
  DBMS_OUTPUT.PUT_LINE(q'~    });~');
  DBMS_OUTPUT.PUT_LINE(q'~    o.push('</svg>');~');
  DBMS_OUTPUT.PUT_LINE(q'~    return '<div class="heat"><div class="hh"><span>Hourly, last 14 days, by hour ending</span><span class="ramp">0%<i></i>100%</span></div>' + o.join('') + '</div>';~');
  DBMS_OUTPUT.PUT_LINE(q'~  }~');
  DBMS_OUTPUT.PUT_LINE(NULL);
  DBMS_OUTPUT.PUT_LINE(q'~  /* ---------- page pieces ---------- */~');
  DBMS_OUTPUT.PUT_LINE(NULL);
  DBMS_OUTPUT.PUT_LINE(q'~  function pill(sev, text) { return '<span class="st ' + SEV_CLASS[sev] + '">' + esc(text || SEV_LABEL[sev]) + '</span>'; }~');
  DBMS_OUTPUT.PUT_LINE(q'~  function sdot(sev) { return '<span class="dot ' + SEV_CLASS[sev] + '"></span>'; }~');
  DBMS_OUTPUT.PUT_LINE(NULL);
  DBMS_OUTPUT.PUT_LINE(q'~  function factsHtml(facts) {~');
  DBMS_OUTPUT.PUT_LINE(q'~    return '<div class="facts">' + facts.map(function (f) {~');
  DBMS_OUTPUT.PUT_LINE(q'~      return '<div class="fact ' + (f.tone || '') + '"><div class="l">' + esc(f.l) + '</div><div class="v">' + f.v + '</div>' +~');
  DBMS_OUTPUT.PUT_LINE(q'~        (f.s ? '<div class="s">' + esc(f.s) + '</div>' : '') + '</div>';~');
  DBMS_OUTPUT.PUT_LINE(q'~    }).join('') + '</div>';~');
  DBMS_OUTPUT.PUT_LINE(q'~  }~');
  DBMS_OUTPUT.PUT_LINE(NULL);
  DBMS_OUTPUT.PUT_LINE(q'~  function tagsHtml(m) {~');
  DBMS_OUTPUT.PUT_LINE(q'~    var t = [];~');
  DBMS_OUTPUT.PUT_LINE(q'~    if (QUALITY_TAG[m.f.q]) t.push(QUALITY_TAG[m.f.q]);~');
  DBMS_OUTPUT.PUT_LINE(q'~    if (m.f.cur === 0) t.push('no longer reported');~');
  DBMS_OUTPUT.PUT_LINE(q'~    if (m.f.limSrc && m.f.limSrc !== 'MAXBYTES' && m.f.limSrc !== 'AUTOEXTEND' && m.fam.id === 'tablespaces') t.push('limit: ' + m.f.limSrc.toLowerCase());~');
  DBMS_OUTPUT.PUT_LINE(q'~    return t.map(function (x) { return '<span class="tag">' + esc(x) + '</span>'; }).join('') +~');
  DBMS_OUTPUT.PUT_LINE(q'~      (m.trk && REL_TAG[m.trk.rel] ? '<span class="tag rel">' + REL_TAG[m.trk.rel] + '</span>' : '');~');
  DBMS_OUTPUT.PUT_LINE(q'~  }~');
  DBMS_OUTPUT.PUT_LINE(NULL);
  DBMS_OUTPUT.PUT_LINE(q'~  /* The forecast track record of the series (CAPR_FIT_TRACK): the view's~');
  DBMS_OUTPUT.PUT_LINE(q'~     sentence, and the +30 band at its factor when that widens the band. */~');
  DBMS_OUTPUT.PUT_LINE(q'~  function trackHtml(m) {~');
  DBMS_OUTPUT.PUT_LINE(q'~    var t = m.trk, cal = '';~');
  DBMS_OUTPUT.PUT_LINE(q'~    if (t.f > 1 && t.lo != null && t.hi != null && t.hi > t.lo) {~');
  DBMS_OUTPUT.PUT_LINE(q'~      cal = ' <span class="cal">+30 d band at that factor: ' + m.unit.fmt(t.lo) + ' \u2013 ' + m.unit.fmt(t.hi) + '</span>';~');
  DBMS_OUTPUT.PUT_LINE(q'~    }~');
  DBMS_OUTPUT.PUT_LINE(q'~    return '<p class="trk' + (REL_TAG[t.rel] ? ' off' : t.rel === 'UNKNOWN' ? ' unk' : '') + '"><span class="tl">Track record</span>' + esc(t.txt) + cal + '</p>';~');
  DBMS_OUTPUT.PUT_LINE(q'~  }~');
  DBMS_OUTPUT.PUT_LINE(NULL);
  DBMS_OUTPUT.PUT_LINE(q'~  function cardHtml(m) {~');
  DBMS_OUTPUT.PUT_LINE(q'~    var spec = chartSpec(m);~');
  DBMS_OUTPUT.PUT_LINE(q'~    var id = CHARTS.length;~');
  DBMS_OUTPUT.PUT_LINE(q'~    var svg = chartSvg(spec, id);~');
  DBMS_OUTPUT.PUT_LINE(q'~    CHARTS.push(spec);~');
  DBMS_OUTPUT.PUT_LINE(q'~    var o = ['<article class="card ' + SEV_CLASS[m.sev] + (m.fam.heat ? ' split' : '') + '" id="' + m.id + '">'];~');
  DBMS_OUTPUT.PUT_LINE(q'~    o.push('<div class="ch"><h3>' + esc(m.name) + '</h3>' + (m.ctr && m.ctr !== m.name ? '<span class="ctr">' + esc(m.ctr) + '</span>' : '') + tagsHtml(m) + pill(m.sev) + '</div>');~');
  DBMS_OUTPUT.PUT_LINE(q'~    var va = m.alerts[0];~');
  DBMS_OUTPUT.PUT_LINE(q'~    if (va && (m.sev === 'CRIT' || m.sev === 'WARN')) {~');
  DBMS_OUTPUT.PUT_LINE(q'~      o.push('<p class="verdict ' + SEV_CLASS[m.sev] + '">' + alertFact(va, m) + ' \u00b7 ' + alertWhen(va) + '</p>');~');
  DBMS_OUTPUT.PUT_LINE(q'~    }~');
  DBMS_OUTPUT.PUT_LINE(q'~    o.push(factsHtml(m.facts));~');
  DBMS_OUTPUT.PUT_LINE(q'~    o.push('<div class="viz"><div><div class="chart" data-chart="' + id + '">' + svg + '<div class="tip"></div></div>');~');
  DBMS_OUTPUT.PUT_LINE(q'~    o.push(legendHtml(spec) + '</div>');~');
  DBMS_OUTPUT.PUT_LINE(q'~    if (m.fam.heat) o.push(heatSvg(m));~');
  DBMS_OUTPUT.PUT_LINE(q'~    o.push('</div>');~');
  DBMS_OUTPUT.PUT_LINE(q'~    if (m.trk) o.push(trackHtml(m));~');
  DBMS_OUTPUT.PUT_LINE(q'~    var shifts = m.anoms.filter(function (a) { return a.ak === 'CPU_SHIFT'; });~');
  DBMS_OUTPUT.PUT_LINE(q'~    var evs = anomalyEvents(m);~');
  DBMS_OUTPUT.PUT_LINE(q'~    if (shifts.length || evs.length) {~');
  DBMS_OUTPUT.PUT_LINE(q'~      o.push('<div class="issues">');~');
  DBMS_OUTPUT.PUT_LINE(q'~      shifts.forEach(function (a) {~');
  DBMS_OUTPUT.PUT_LINE(q'~        o.push('<div class="iss">' + sdot(a.sev && SEV_RANK[a.sev] != null ? a.sev : 'INFO') + '<span>Level shift <b>' + sign(a.shift) + num(Math.abs(a.shift), 1) + '%</b> since ' + fDay(dayN(a.ts)) + '</span></div>');~');
  DBMS_OUTPUT.PUT_LINE(q'~      });~');
  DBMS_OUTPUT.PUT_LINE(q'~      if (evs.length) {~');
  DBMS_OUTPUT.PUT_LINE(q'~        var shown = evs.slice(0, 3);~');
  DBMS_OUTPUT.PUT_LINE(q'~        o.push('<div class="anoms"><div class="ah"><span>Unusual days</span><span>' + evs.length + ' in the last ' + ANOM_DAYS + ' d</span></div>' +~');
  DBMS_OUTPUT.PUT_LINE(q'~          shown.map(function (e) { return anomalyChip(e, m); }).join('') + '</div>');~');
  DBMS_OUTPUT.PUT_LINE(q'~      }~');
  DBMS_OUTPUT.PUT_LINE(q'~      o.push('</div>');~');
  DBMS_OUTPUT.PUT_LINE(q'~    }~');
  DBMS_OUTPUT.PUT_LINE(q'~    o.push('</article>');~');
  DBMS_OUTPUT.PUT_LINE(q'~    return o.join('');~');
  DBMS_OUTPUT.PUT_LINE(q'~  }~');
  DBMS_OUTPUT.PUT_LINE(NULL);
  DBMS_OUTPUT.PUT_LINE(q'~  function rowHtml(m) {~');
  DBMS_OUTPUT.PUT_LINE(q'~    var f = m.f;~');
  DBMS_OUTPUT.PUT_LINE(q'~    var pct = f.pct != null ? Math.max(0, Math.min(100, f.pct)) : null;~');
  DBMS_OUTPUT.PUT_LINE(q'~    var tone = pctTone(f.pct, m.fam.id === 'tablespaces' ? K.nfWarn : SERIES_SAT, m.fam.id === 'tablespaces' ? K.nfCrit : 100);~');
  DBMS_OUTPUT.PUT_LINE(q'~    var dtf = dtfFact(f, '');~');
  DBMS_OUTPUT.PUT_LINE(q'~    return '<div class="row" id="' + m.id + '"><div class="nm"><b>' + esc(m.name) + '</b><span>' + esc(m.ctr) + (QUALITY_TAG[f.q] ? ' \u00b7 ' + QUALITY_TAG[f.q] : '') + '</span></div>' +~');
  DBMS_OUTPUT.PUT_LINE(q'~      sparkSvg(m, 200, 30) +~');
  DBMS_OUTPUT.PUT_LINE(q'~      '<div class="c keep">' + (pct != null ? num(f.pct, 1) + '%<div class="bar"><i class="' + tone + '" style="width:' + pct + '%"></i></div>' : m.unit.fmt(f.v)) + '</div>' +~');
  DBMS_OUTPUT.PUT_LINE(q'~      '<div class="c">' + m.unit.rate(f.slope) + '<span>growth</span></div>' +~');
  DBMS_OUTPUT.PUT_LINE(q'~      '<div class="c">' + dtf.v + '<span>' + esc(dtf.s) + '</span></div>' + pill(m.sev) + '</div>';~');
  DBMS_OUTPUT.PUT_LINE(q'~  }~');
  DBMS_OUTPUT.PUT_LINE(NULL);
  DBMS_OUTPUT.PUT_LINE(q'~  function familySummary(fam, ms) {~');
  DBMS_OUTPUT.PUT_LINE(q'~    var c = { CRIT: 0, WARN: 0, INFO: 0 };~');
  DBMS_OUTPUT.PUT_LINE(q'~    ms.forEach(function (m) { if (c[m.sev] != null) c[m.sev]++; });~');
  DBMS_OUTPUT.PUT_LINE(q'~    var parts = ['<b>' + ms.length + '</b> ' + fam.noun + (ms.length === 1 ? '' : 's')];~');
  DBMS_OUTPUT.PUT_LINE(q'~    if (c.CRIT) parts.push('<b>' + c.CRIT + '</b> critical');~');
  DBMS_OUTPUT.PUT_LINE(q'~    if (c.WARN) parts.push('<b>' + c.WARN + '</b> warning');~');
  DBMS_OUTPUT.PUT_LINE(q'~    var soon = ms.filter(function (m) { return m.f.dtf != null && m.f.q === 'OK'; })~');
  DBMS_OUTPUT.PUT_LINE(q'~      .sort(function (a, b) { return a.f.dtf - b.f.dtf; })[0];~');
  DBMS_OUTPUT.PUT_LINE(q'~    if (soon && !fam.flow) {~');
  DBMS_OUTPUT.PUT_LINE(q'~      var what = fam.id === 'tablespaces' ? 'full' : fam.id.indexOf('cpu') >= 0 ? CPU_SAT + '%' : SERIES_SAT + '%';~');
  DBMS_OUTPUT.PUT_LINE(q'~      parts.push('soonest ' + what + ': <b>' + esc(soon.name) + '</b> in ' + fDays(soon.f.dtf));~');
  DBMS_OUTPUT.PUT_LINE(q'~    }~');
  DBMS_OUTPUT.PUT_LINE(q'~    return parts.map(function (p) { return '<span>' + p + '</span>'; }).join('');~');
  DBMS_OUTPUT.PUT_LINE(q'~  }~');
  DBMS_OUTPUT.PUT_LINE(NULL);
  DBMS_OUTPUT.PUT_LINE(q'~  function headline(fam, ms) {~');
  DBMS_OUTPUT.PUT_LINE(q'~    var m = ms[0];~');
  DBMS_OUTPUT.PUT_LINE(q'~    if (!m) return '';~');
  DBMS_OUTPUT.PUT_LINE(q'~    var a = m.alerts[0];~');
  DBMS_OUTPUT.PUT_LINE(q'~    if (a && m.sev !== 'OK') {~');
  DBMS_OUTPUT.PUT_LINE(q'~      var fact = /_ANOM$/.test(a.kind) ? 'unusual ' + fDay(dayN(a.day)) : alertFact(a, m).replace(/<\/?b>/g, '');~');
  DBMS_OUTPUT.PUT_LINE(q'~      return '<b>' + esc(m.name) + '</b> ' + fact;~');
  DBMS_OUTPUT.PUT_LINE(q'~    }~');
  DBMS_OUTPUT.PUT_LINE(q'~    var f = m.f;~');
  DBMS_OUTPUT.PUT_LINE(q'~    if (fam.id === 'tablespaces') {~');
  DBMS_OUTPUT.PUT_LINE(q'~      var full = ms.slice().sort(function (x, y) { return (y.f.pct || 0) - (x.f.pct || 0); })[0];~');
  DBMS_OUTPUT.PUT_LINE(q'~      return 'fullest <b>' + esc(full.name) + '</b> ' + num(full.f.pct, 1) + '%';~');
  DBMS_OUTPUT.PUT_LINE(q'~    }~');
  DBMS_OUTPUT.PUT_LINE(q'~    if (f.k === 'CPU') return '<b>' + esc(m.name) + '</b> p95 ' + num(f.v, 1) + '%';~');
  DBMS_OUTPUT.PUT_LINE(q'~    if (fam.flow) return '<b>' + m.unit.fmt(lastVal(m.pts)) + '</b> ' + fam.flow;~');
  DBMS_OUTPUT.PUT_LINE(q'~    return '<b>' + esc(m.name) + '</b> ' + m.unit.fmt(f.v) + (f.pct != null ? ' \u00b7 ' + num(f.pct, 1) + '%' : '');~');
  DBMS_OUTPUT.PUT_LINE(q'~  }~');
  DBMS_OUTPUT.PUT_LINE(NULL);
  DBMS_OUTPUT.PUT_LINE(q'~  /* ---------- overview: space growth rates ---------- */~');
  DBMS_OUTPUT.PUT_LINE(NULL);
  DBMS_OUTPUT.PUT_LINE(q'~  var SPACE_TOP = 5;~');
  DBMS_OUTPUT.PUT_LINE(NULL);
  DBMS_OUTPUT.PUT_LINE(q'~  function famMetrics(id) {~');
  DBMS_OUTPUT.PUT_LINE(q'~    var s = sections.filter(function (x) { return x.fam.id === id; })[0];~');
  DBMS_OUTPUT.PUT_LINE(q'~    return s ? s.ms : [];~');
END;
/
BEGIN
  DBMS_OUTPUT.PUT_LINE(q'~  }~');
  DBMS_OUTPUT.PUT_LINE(q'~  /* The rate a tablespace fills at: a cyclic one is judged on its peaks. */~');
  DBMS_OUTPUT.PUT_LINE(q'~  function fillRate(f) { return f.q === 'CYCLIC' ? f.pkSlope : f.slope; }~');
  DBMS_OUTPUT.PUT_LINE(q'~  function observedChange(pts, days) {~');
  DBMS_OUTPUT.PUT_LINE(q'~    var last = null, first = null;~');
  DBMS_OUTPUT.PUT_LINE(q'~    for (var i = pts.length - 1; i >= 0; i--) {~');
  DBMS_OUTPUT.PUT_LINE(q'~      var p = pts[i];~');
  DBMS_OUTPUT.PUT_LINE(q'~      if (p.y == null) continue;~');
  DBMS_OUTPUT.PUT_LINE(q'~      if (last == null) last = p;~');
  DBMS_OUTPUT.PUT_LINE(q'~      if (p.x >= last.x - days) first = p; else break;~');
  DBMS_OUTPUT.PUT_LINE(q'~    }~');
  DBMS_OUTPUT.PUT_LINE(q'~    return last && first && last.x > first.x ? { d: last.y - first.y, n: last.x - first.x } : null;~');
  DBMS_OUTPUT.PUT_LINE(q'~  }~');
  DBMS_OUTPUT.PUT_LINE(NULL);
  DBMS_OUTPUT.PUT_LINE(q'~  function spaceRow(m, cells) {~');
  DBMS_OUTPUT.PUT_LINE(q'~    return '<a class="grow" href="#' + m.id + '"><span class="s">' + esc(m.name) + ' <span>' + esc(m.ctr) +~');
  DBMS_OUTPUT.PUT_LINE(q'~      (QUALITY_TAG[m.f.q] ? ' \u00b7 ' + QUALITY_TAG[m.f.q] : '') + '</span></span>' +~');
  DBMS_OUTPUT.PUT_LINE(q'~      cells.map(function (c) { return '<span class="c">' + c + '</span>'; }).join('') + '</a>';~');
  DBMS_OUTPUT.PUT_LINE(q'~  }~');
  DBMS_OUTPUT.PUT_LINE(NULL);
  DBMS_OUTPUT.PUT_LINE(q'~  /* The tablespace with the fewest days to full, as one sentence. */~');
  DBMS_OUTPUT.PUT_LINE(q'~  function fillsFirstHtml(ts) {~');
  DBMS_OUTPUT.PUT_LINE(q'~    var first = ts.filter(function (m) { return m.f.dtf != null && m.f.q !== 'INSUFFICIENT_HISTORY'; })~');
  DBMS_OUTPUT.PUT_LINE(q'~      .sort(function (a, b) { return a.f.dtf - b.f.dtf; })[0];~');
  DBMS_OUTPUT.PUT_LINE(q'~    if (!first) return '<div class="lead">No tablespace is on course to fill.</div>';~');
  DBMS_OUTPUT.PUT_LINE(q'~    var f = first.f, tone = dtfFact(f, '').tone;~');
  DBMS_OUTPUT.PUT_LINE(q'~    return '<a class="lead" href="#' + first.id + '">Fills first: <b>' + esc(first.name) + '</b> <span>' + esc(first.ctr) +~');
  DBMS_OUTPUT.PUT_LINE(q'~      (QUALITY_TAG[f.q] ? ' \u00b7 ' + QUALITY_TAG[f.q] : '') + '</span>, ' +~');
  DBMS_OUTPUT.PUT_LINE(q'~      (f.dtf > 3650 ? 'full <b>not in sight</b>' : 'full in <b class="' + (tone || '') + '">' + fDays(f.dtf) + '</b> (' + (f.dtf > 120 ? Math.round(f.dtf) + ' d, ' : '') + 'by ' + fDayY(Math.round(LAST + f.dtf)) + ')') +~');
  DBMS_OUTPUT.PUT_LINE(q'~      ' at ' + first.unit.rate(fillRate(f)) + ', ' + num(f.pct, 1) + '% used now</a>';~');
  DBMS_OUTPUT.PUT_LINE(q'~  }~');
  DBMS_OUTPUT.PUT_LINE(NULL);
  DBMS_OUTPUT.PUT_LINE(q'~  /* The disk the datafiles of a database share (CAPR_DISK): one sentence each. */~');
  DBMS_OUTPUT.PUT_LINE(q'~  function diskHtml() {~');
  DBMS_OUTPUT.PUT_LINE(q'~    var ds = D.disks || [];~');
  DBMS_OUTPUT.PUT_LINE(q'~    if (!ds.length) return '';~');
  DBMS_OUTPUT.PUT_LINE(q'~    return '<h3>Shared disk</h3>' + ds.map(function (d) {~');
  DBMS_OUTPUT.PUT_LINE(q'~      var head = '<div class="lead">' + esc(d.db) + ' <span>' + esc(d.disk) + '</span>: ';~');
  DBMS_OUTPUT.PUT_LINE(q'~      if (d.free == null) return head + 'free space not known. Set it in CAP_DISK_OVERRIDE to forecast the disk.</div>';~');
  DBMS_OUTPUT.PUT_LINE(q'~      var tone = d.sev === 'CRIT' ? 'crit' : d.sev === 'WARN' ? 'warn' : '';~');
  DBMS_OUTPUT.PUT_LINE(q'~      return head + '<b>' + num(d.free, 1) + ' GiB</b> free (' +~');
  DBMS_OUTPUT.PUT_LINE(q'~        (d.src === 'OVERRIDE' ? 'set by the operator' : 'from the live tablespace ceilings') + (d.asOf ? ', ' + fDay(dayN(d.asOf)) : '') + '), ' +~');
  DBMS_OUTPUT.PUT_LINE(q'~        (d.dtf != null ? 'full in <b class="' + tone + '">' + fDays(d.dtf) + '</b>' + (d.fullDay ? ' (by ' + fDayY(dayN(d.fullDay)) + (d.dtfW != null ? ', worst case ' + fDays(d.dtfW) : '') + ')' : '')~');
  DBMS_OUTPUT.PUT_LINE(q'~          : 'does <b>not fill</b> at the fitted rates') +~');
  DBMS_OUTPUT.PUT_LINE(q'~        '. ' + (d.nGrow || 0) + ' growing tablespaces take ' + num(d.grow, 1) + ' MiB a day' + (d.top ? ': ' + esc(d.top) + ' MiB/day' : '') + '</div>';~');
  DBMS_OUTPUT.PUT_LINE(q'~    }).join('');~');
  DBMS_OUTPUT.PUT_LINE(q'~  }~');
  DBMS_OUTPUT.PUT_LINE(NULL);
  DBMS_OUTPUT.PUT_LINE(q'~  function spaceHtml() {~');
  DBMS_OUTPUT.PUT_LINE(q'~    var ts = famMetrics('tablespaces'), dbs = famMetrics('db-size');~');
  DBMS_OUTPUT.PUT_LINE(q'~    if (!ts.length && !dbs.length) return '';~');
  DBMS_OUTPUT.PUT_LINE(q'~    var out = ['<div class="rates">'];~');
  DBMS_OUTPUT.PUT_LINE(NULL);
  DBMS_OUTPUT.PUT_LINE(q'~    if (dbs.length) {~');
  DBMS_OUTPUT.PUT_LINE(q'~      out.push('<h3>Database size</h3><div class="ghead"><span></span><span>size</span><span>per day</span><span>per 30 d</span><span>last 30 d</span></div>');~');
  DBMS_OUTPUT.PUT_LINE(q'~      dbs.forEach(function (m) {~');
  DBMS_OUTPUT.PUT_LINE(q'~        var f = m.f, obs = observedChange(m.pts, 30);~');
  DBMS_OUTPUT.PUT_LINE(q'~        out.push(spaceRow(m, [m.unit.fmt(f.v), m.unit.rate(f.slope),~');
  DBMS_OUTPUT.PUT_LINE(q'~          f.slope == null ? '\u2013' : sign(f.slope) + m.unit.fmt(Math.abs(f.slope) * 30),~');
  DBMS_OUTPUT.PUT_LINE(q'~          obs ? sign(obs.d) + m.unit.fmt(Math.abs(obs.d)) : '\u2013']));~');
  DBMS_OUTPUT.PUT_LINE(q'~      });~');
  DBMS_OUTPUT.PUT_LINE(q'~    }~');
  DBMS_OUTPUT.PUT_LINE(q'~    if (ts.length) {~');
  DBMS_OUTPUT.PUT_LINE(q'~      var fastest = ts.filter(function (m) { return fillRate(m.f) > 0; }).sort(function (a, b) {~');
  DBMS_OUTPUT.PUT_LINE(q'~        var da = a.f.dtf == null ? 1e9 : a.f.dtf, db = b.f.dtf == null ? 1e9 : b.f.dtf;~');
  DBMS_OUTPUT.PUT_LINE(q'~        return da - db || fillRate(b.f) - fillRate(a.f);~');
  DBMS_OUTPUT.PUT_LINE(q'~      }).slice(0, SPACE_TOP);~');
  DBMS_OUTPUT.PUT_LINE(q'~      out.push('<h3>Fastest-filling tablespaces</h3>' + fillsFirstHtml(ts));~');
  DBMS_OUTPUT.PUT_LINE(q'~      if (!fastest.length) out.push('<div class="allok">No tablespace is growing</div>');~');
  DBMS_OUTPUT.PUT_LINE(q'~      else out.push('<div class="ghead"><span></span><span>used</span><span>per day</span><span>per 30 d</span><span>full in</span></div>');~');
  DBMS_OUTPUT.PUT_LINE(q'~      fastest.forEach(function (m) {~');
  DBMS_OUTPUT.PUT_LINE(q'~        var f = m.f, r = fillRate(f);~');
  DBMS_OUTPUT.PUT_LINE(q'~        out.push(spaceRow(m, [num(f.pct, 1) + '%', m.unit.rate(r), sign(r) + fBytes(Math.abs(r) * 30), dtfFact(f, '').v]));~');
  DBMS_OUTPUT.PUT_LINE(q'~      });~');
  DBMS_OUTPUT.PUT_LINE(q'~      out.push(diskHtml());~');
  DBMS_OUTPUT.PUT_LINE(q'~    }~');
  DBMS_OUTPUT.PUT_LINE(q'~    out.push('</div>');~');
  DBMS_OUTPUT.PUT_LINE(q'~    return out.join('');~');
  DBMS_OUTPUT.PUT_LINE(q'~  }~');
  DBMS_OUTPUT.PUT_LINE(NULL);
  DBMS_OUTPUT.PUT_LINE(q'~  /* ---------- memory: sizing verdicts per instance (advice, not alerts) ---------- */~');
  DBMS_OUTPUT.PUT_LINE(NULL);
  DBMS_OUTPUT.PUT_LINE(q'~  var GRADE_LABEL = {~');
  DBMS_OUTPUT.PUT_LINE(q'~    UNDERSIZED: 'undersized', OVERSIZED: 'oversized', THRASHING: 'thrashing', DRIFTING: 'drifting',~');
  DBMS_OUTPUT.PUT_LINE(q'~    OK: 'OK', INSUFFICIENT_EVIDENCE: 'insufficient evidence'~');
  DBMS_OUTPUT.PUT_LINE(q'~  };~');
  DBMS_OUTPUT.PUT_LINE(q'~  var GRADE_ORDER = { UNDERSIZED: 0, THRASHING: 0, DRIFTING: 1, OVERSIZED: 2 };~');
  DBMS_OUTPUT.PUT_LINE(q'~  var DIR_MARK = { PRESSURE: ['pr', '\u25b2 pressure'], SLACK: ['sl', '\u25bc slack'], NEUTRAL: ['nu', '\u00b7 neutral'] };~');
  DBMS_OUTPUT.PUT_LINE(q'~  var MEM_EV = groupBy(D.memEvidence, function (e) { return key(e.dbid, e.inst, e.area); });~');
  DBMS_OUTPUT.PUT_LINE(q'~  var MEM_PTS = groupBy(D.memPoints, function (p) { return key(p.dbid, p.inst); });~');
  DBMS_OUTPUT.PUT_LINE(q'~  var MEM_V = groupBy(D.memVerdicts, function (v) { return key(v.dbid, v.inst); });~');
  DBMS_OUTPUT.PUT_LINE(q'~  var memCards = Object.keys(MEM_V).map(function (k) {~');
  DBMS_OUTPUT.PUT_LINE(q'~    var vs = MEM_V[k].slice().sort(function (a, b) { return a.ar - b.ar; });~');
  DBMS_OUTPUT.PUT_LINE(q'~    return { v: vs[0], vs: vs, id: 'memory-' + vs[0].dbid + '-' + vs[0].inst, pts: MEM_PTS[k] || [] };~');
  DBMS_OUTPUT.PUT_LINE(q'~  });~');
  DBMS_OUTPUT.PUT_LINE(q'~  var memInstances = groupBy(memCards, function (c) { return c.v.dbid; });~');
  DBMS_OUTPUT.PUT_LINE(q'~  var MCHARTS = [];~');
  DBMS_OUTPUT.PUT_LINE(q'~  var MW = 480, MH = 200, MML = 44, MMR = 10, MMT = 22, MMB = 24;~');
  DBMS_OUTPUT.PUT_LINE(NULL);
  DBMS_OUTPUT.PUT_LINE(q'~  function gradeName(g) { return GRADE_LABEL[g] || String(g || '').toLowerCase().replace(/_/g, ' '); }~');
  DBMS_OUTPUT.PUT_LINE(q'~  function gradeTone(v) { return v.act === 'Y' ? 'act' : v.g === 'INSUFFICIENT_EVIDENCE' ? 'ie' : 'ok'; }~');
  DBMS_OUTPUT.PUT_LINE(q'~  /* As the view prints a size: whole GiB when it is a multiple of 1 GiB, else whole MiB. */~');
  DBMS_OUTPUT.PUT_LINE(q'~  function memSize(b) {~');
  DBMS_OUTPUT.PUT_LINE(q'~    if (b == null) return '\u2013';~');
  DBMS_OUTPUT.PUT_LINE(q'~    return b % Math.pow(1024, 3) === 0 ? b / Math.pow(1024, 3) + ' GiB' : Math.round(b / Math.pow(1024, 2)) + ' MiB';~');
  DBMS_OUTPUT.PUT_LINE(q'~  }~');
  DBMS_OUTPUT.PUT_LINE(q'~  function memRange(lo, hi) {~');
  DBMS_OUTPUT.PUT_LINE(q'~    var a = memSize(lo), b = memSize(hi);~');
  DBMS_OUTPUT.PUT_LINE(q'~    return a.slice(-4) === b.slice(-4) ? a.slice(0, -4) + '\u2013' + b : a + ' \u2013 ' + b;~');
  DBMS_OUTPUT.PUT_LINE(q'~  }~');
  DBMS_OUTPUT.PUT_LINE(q'~  function memName(c) {~');
  DBMS_OUTPUT.PUT_LINE(q'~    var n = conLabel(c.v.dbid, c.v.con);~');
  DBMS_OUTPUT.PUT_LINE(q'~    return memInstances[c.v.dbid].length > 1 ? n + ' instance ' + c.v.inst : n;~');
  DBMS_OUTPUT.PUT_LINE(q'~  }~');
  DBMS_OUTPUT.PUT_LINE(NULL);
  DBMS_OUTPUT.PUT_LINE(q'~  /* The component points as stacked bands: the largest component at the bottom. */~');
  DBMS_OUTPUT.PUT_LINE(q'~  function memStack(pts) {~');
  DBMS_OUTPUT.PUT_LINE(q'~    var comps = pts.map(function (p) {~');
  DBMS_OUTPUT.PUT_LINE(q'~      var t0 = dayN(p.t0), byX = {}, lastX = null, cur = 0, lo = null, hi = null, ops = 0;~');
  DBMS_OUTPUT.PUT_LINE(q'~      p.d.forEach(function (r) {~');
  DBMS_OUTPUT.PUT_LINE(q'~        var x = t0 + r[0], b = r[1] || 0;~');
  DBMS_OUTPUT.PUT_LINE(q'~        byX[x] = { b: b, lo: r[2], hi: r[3], ops: r[4] || 0 };~');
  DBMS_OUTPUT.PUT_LINE(q'~        if (lastX == null || x > lastX) { lastX = x; cur = b; }~');
  DBMS_OUTPUT.PUT_LINE(q'~        if (r[2] != null) lo = lo == null ? r[2] : Math.min(lo, r[2]);~');
  DBMS_OUTPUT.PUT_LINE(q'~        if (r[3] != null) hi = hi == null ? r[3] : Math.max(hi, r[3]);~');
  DBMS_OUTPUT.PUT_LINE(q'~        ops += r[4] || 0;~');
  DBMS_OUTPUT.PUT_LINE(q'~      });~');
  DBMS_OUTPUT.PUT_LINE(q'~      return { c: p.c, byX: byX, cur: cur, lo: lo, hi: hi, ops: ops };~');
  DBMS_OUTPUT.PUT_LINE(q'~    }).sort(function (a, b) { return b.cur - a.cur || (a.c < b.c ? -1 : 1); });~');
  DBMS_OUTPUT.PUT_LINE(q'~    comps.forEach(function (c, i) { c.cls = 'mc' + (i % 6); });~');
  DBMS_OUTPUT.PUT_LINE(q'~    var seen = {};~');
  DBMS_OUTPUT.PUT_LINE(q'~    comps.forEach(function (c) { Object.keys(c.byX).forEach(function (x) { seen[x] = 1; }); });~');
  DBMS_OUTPUT.PUT_LINE(q'~    var days = Object.keys(seen).map(Number).sort(function (a, b) { return a - b; });~');
  DBMS_OUTPUT.PUT_LINE(q'~    var total = comps.reduce(function (s, c) { return s + c.cur; }, 0);~');
  DBMS_OUTPUT.PUT_LINE(q'~    return { comps: comps, days: days, total: total };~');
  DBMS_OUTPUT.PUT_LINE(q'~  }~');
  DBMS_OUTPUT.PUT_LINE(q'~  function memAt(c, d) { return c.byX[d] ? c.byX[d].b : 0; }~');
  DBMS_OUTPUT.PUT_LINE(q'~  function memMoved(c, d) { var p = c.byX[d]; return !!p && (p.ops > 0 || (p.lo != null && p.hi != null && p.hi > p.lo)); }~');
  DBMS_OUTPUT.PUT_LINE(NULL);
  DBMS_OUTPUT.PUT_LINE(q'~  function memChartSvg(st, id) {~');
  DBMS_OUTPUT.PUT_LINE(q'~    var days = st.days, x1 = days[days.length - 1], x0 = days.length > 1 ? days[0] : x1 - 1;~');
  DBMS_OUTPUT.PUT_LINE(q'~    var ymax = 0;~');
  DBMS_OUTPUT.PUT_LINE(q'~    days.forEach(function (d) { ymax = Math.max(ymax, st.comps.reduce(function (s, c) { return s + memAt(c, d); }, 0)); });~');
  DBMS_OUTPUT.PUT_LINE(q'~    var u = unitFor('bytes', ymax);~');
  DBMS_OUTPUT.PUT_LINE(q'~    var nt = niceTicks(0, (ymax || 1) * 1.04 / u.scale, 4);~');
  DBMS_OUTPUT.PUT_LINE(q'~    var top = nt.ticks[nt.ticks.length - 1] * u.scale;~');
  DBMS_OUTPUT.PUT_LINE(q'~    if (top < ymax * 1.02) top = (nt.ticks[nt.ticks.length - 1] + nt.step) * u.scale;~');
  DBMS_OUTPUT.PUT_LINE(q'~    var xs = function (x) { return MML + (x - x0) / (x1 - x0) * (MW - MML - MMR); };~');
  DBMS_OUTPUT.PUT_LINE(q'~    var ys = function (y) { return MMT + (1 - y / (top || 1)) * (MH - MMT - MMB); };~');
  DBMS_OUTPUT.PUT_LINE(q'~    var o = ['<svg viewBox="0 0 ' + MW + ' ' + MH + '" role="img" aria-label="SGA components by day">'];~');
  DBMS_OUTPUT.PUT_LINE(q'~    nt.ticks.forEach(function (t) {~');
  DBMS_OUTPUT.PUT_LINE(q'~      var y = ys(t * u.scale).toFixed(1);~');
  DBMS_OUTPUT.PUT_LINE(q'~      o.push('<line x1="' + MML + '" x2="' + (MW - MMR) + '" y1="' + y + '" y2="' + y + '" stroke="var(--line-2)"/>');~');
  DBMS_OUTPUT.PUT_LINE(q'~      o.push('<text x="' + (MML - 6) + '" y="' + (+y + 3.5).toFixed(1) + '" text-anchor="end">' + num(t, nt.dp) + '</text>');~');
  DBMS_OUTPUT.PUT_LINE(q'~    });~');
  DBMS_OUTPUT.PUT_LINE(q'~    o.push('<text x="' + (MML - 6) + '" y="10" text-anchor="end">' + u.short + '</text>');~');
  DBMS_OUTPUT.PUT_LINE(q'~    var base = days.map(function () { return 0; });~');
  DBMS_OUTPUT.PUT_LINE(q'~    st.comps.forEach(function (c) {~');
  DBMS_OUTPUT.PUT_LINE(q'~      var hi = days.map(function (d, i) { return base[i] + memAt(c, d); });~');
  DBMS_OUTPUT.PUT_LINE(q'~      var up = days.map(function (d, i) { return xs(d).toFixed(1) + ',' + ys(hi[i]).toFixed(1); });~');
  DBMS_OUTPUT.PUT_LINE(q'~      var down = days.map(function (d, i) { return xs(d).toFixed(1) + ',' + ys(base[i]).toFixed(1); }).reverse();~');
  DBMS_OUTPUT.PUT_LINE(q'~      if (days.length === 1) {~');
  DBMS_OUTPUT.PUT_LINE(q'~        up.unshift(xs(x0).toFixed(1) + ',' + ys(hi[0]).toFixed(1));~');
  DBMS_OUTPUT.PUT_LINE(q'~        down.push(xs(x0).toFixed(1) + ',' + ys(base[0]).toFixed(1));~');
  DBMS_OUTPUT.PUT_LINE(q'~      }~');
  DBMS_OUTPUT.PUT_LINE(q'~      o.push('<path class="' + c.cls + '" d="M' + up.join('L') + 'L' + down.join('L') + 'Z" stroke="var(--surface)" stroke-width=".75" stroke-linejoin="round"/>');~');
  DBMS_OUTPUT.PUT_LINE(q'~      base = hi;~');
  DBMS_OUTPUT.PUT_LINE(q'~    });~');
  DBMS_OUTPUT.PUT_LINE(q'~    o.push('<line x1="' + MML + '" x2="' + (MW - MMR) + '" y1="' + ys(0).toFixed(1) + '" y2="' + ys(0).toFixed(1) + '" stroke="var(--line)"/>');~');
  DBMS_OUTPUT.PUT_LINE(q'~    days.forEach(function (d) {~');
  DBMS_OUTPUT.PUT_LINE(q'~      if (st.comps.some(function (c) { return memMoved(c, d); })) {~');
  DBMS_OUTPUT.PUT_LINE(q'~        o.push('<rect class="mrz" x="' + (xs(d) - 1.5).toFixed(1) + '" y="' + (MH - MMB + 2) + '" width="3" height="6" fill="var(--accent)"/>');~');
  DBMS_OUTPUT.PUT_LINE(q'~      }~');
  DBMS_OUTPUT.PUT_LINE(q'~    });~');
  DBMS_OUTPUT.PUT_LINE(q'~    for (var d = x1; d >= x0; d -= 7) {~');
  DBMS_OUTPUT.PUT_LINE(q'~      var x = xs(d);~');
  DBMS_OUTPUT.PUT_LINE(q'~      o.push('<line x1="' + x.toFixed(1) + '" x2="' + x.toFixed(1) + '" y1="' + (MH - MMB) + '" y2="' + (MH - MMB + 4) + '" stroke="var(--line)"/>');~');
  DBMS_OUTPUT.PUT_LINE(q'~      o.push('<text x="' + x.toFixed(1) + '" y="' + (MH - 7) + '" text-anchor="' + (x > MW - MMR - 20 ? 'end' : 'middle') + '">' + fDay(d) + '</text>');~');
  DBMS_OUTPUT.PUT_LINE(q'~    }~');
  DBMS_OUTPUT.PUT_LINE(q'~    o.push('<line class="hx" x1="0" x2="0" y1="' + MMT + '" y2="' + (MH - MMB) + '" stroke="var(--ink-2)" stroke-width="1" visibility="hidden"/>');~');
  DBMS_OUTPUT.PUT_LINE(q'~    o.push('<rect x="' + MML + '" y="0" width="' + (MW - MML - MMR) + '" height="' + (MH - MMB) + '" fill="transparent" class="hit"/>');~');
  DBMS_OUTPUT.PUT_LINE(q'~    o.push('</svg>');~');
  DBMS_OUTPUT.PUT_LINE(q'~    MCHARTS[id] = { st: st, x0: x0, x1: x1, xs: xs };~');
  DBMS_OUTPUT.PUT_LINE(q'~    return o.join('');~');
  DBMS_OUTPUT.PUT_LINE(q'~  }~');
  DBMS_OUTPUT.PUT_LINE(NULL);
  DBMS_OUTPUT.PUT_LINE(q'~  function memLegendHtml(st) {~');
  DBMS_OUTPUT.PUT_LINE(q'~    return '<div class="mlg"><div class="mlh"><span>SGA component</span><span>now</span><span>share</span><span>in the window</span></div>' +~');
  DBMS_OUTPUT.PUT_LINE(q'~      st.comps.map(function (c) {~');
  DBMS_OUTPUT.PUT_LINE(q'~        var moved = c.ops > 0 || (c.lo != null && c.hi != null && c.hi > c.lo);~');
  DBMS_OUTPUT.PUT_LINE(q'~        return '<div class="mlr"><span class="mn"><i class="' + c.cls + '"></i>' + esc(c.c) + '</span><span>' + memSize(c.cur) + '</span>' +~');
  DBMS_OUTPUT.PUT_LINE(q'~          '<span>' + (st.total ? num(100 * c.cur / st.total, 1) + '%' : '\u2013') + '</span>' +~');
  DBMS_OUTPUT.PUT_LINE(q'~          '<span class="' + (moved ? 'mvd' : '') + '">' + (moved ? memRange(c.lo, c.hi) + ' \u00b7 ' + c.ops + ' op' + (c.ops === 1 ? '' : 's') : 'not resized') + '</span></div>';~');
  DBMS_OUTPUT.PUT_LINE(q'~      }).join('') +~');
  DBMS_OUTPUT.PUT_LINE(q'~      '<div class="mlf"><span><i class="mrzk"></i>a component was resized that day</span><span>total ' + memSize(st.total) + '</span></div></div>';~');
  DBMS_OUTPUT.PUT_LINE(q'~  }~');
  DBMS_OUTPUT.PUT_LINE(NULL);
  DBMS_OUTPUT.PUT_LINE(q'~  function memEvidenceHtml(v) {~');
  DBMS_OUTPUT.PUT_LINE(q'~    var ev = MEM_EV[key(v.dbid, v.inst, v.area)] || [];~');
  DBMS_OUTPUT.PUT_LINE(q'~    if (!ev.length) return '';~');
  DBMS_OUTPUT.PUT_LINE(q'~    var np = ev.filter(function (e) { return e.dir === 'PRESSURE'; }).length;~');
  DBMS_OUTPUT.PUT_LINE(q'~    return '<details class="mev"><summary>Evidence <span>' + ev.length + ' signal' + (ev.length === 1 ? '' : 's') + (np ? ', ' + np + ' pressure' : '') + '</span></summary><ul>' +~');
  DBMS_OUTPUT.PUT_LINE(q'~      ev.map(function (e) {~');
  DBMS_OUTPUT.PUT_LINE(q'~        var dm = DIR_MARK[e.dir] || ['nu', String(e.dir || '').toLowerCase()];~');
  DBMS_OUTPUT.PUT_LINE(q'~        return '<li class="' + dm[0] + '"><span class="dir">' + esc(dm[1]) + '</span><span class="kd">' + esc(String(e.kind || '').toLowerCase()) + '</span><span>' + esc(e.txt) + '</span></li>';~');
  DBMS_OUTPUT.PUT_LINE(q'~      }).join('') + '</ul></details>';~');
  DBMS_OUTPUT.PUT_LINE(q'~  }~');
  DBMS_OUTPUT.PUT_LINE(NULL);
  DBMS_OUTPUT.PUT_LINE(q'~  function memRowHtml(v) {~');
  DBMS_OUTPUT.PUT_LINE(q'~    var cur = v.curS || (v.cur != null ? memSize(v.cur) : '\u2013');~');
  DBMS_OUTPUT.PUT_LINE(q'~    var sz = '<span class="mcur">' + esc(cur) + '</span>';~');
  DBMS_OUTPUT.PUT_LINE(q'~    /* The view leaves change_pct NULL when the suggestion is a pool floor (SGA_BALANCE), not a new current size. */~');
  DBMS_OUTPUT.PUT_LINE(q'~    if (v.sugS && v.chg != null) {~');
  DBMS_OUTPUT.PUT_LINE(q'~      sz += '<span class="arr">\u2192</span><b>' + esc(v.sugS) + '</b><span class="chg">' + sign(v.chg) + num(Math.abs(v.chg), v.chg % 1 ? 1 : 0) + '%</span>';~');
  DBMS_OUTPUT.PUT_LINE(q'~    } else if (v.sugS) {~');
  DBMS_OUTPUT.PUT_LINE(q'~      sz += '<span class="arr">\u00b7</span>floor <b>' + esc(v.sugS) + '</b>';~');
  DBMS_OUTPUT.PUT_LINE(q'~    }~');
  DBMS_OUTPUT.PUT_LINE(q'~    if (v.par) sz += '<code>' + esc(v.par) + '</code>';~');
  DBMS_OUTPUT.PUT_LINE(q'~    var flags = [];~');
  DBMS_OUTPUT.PUT_LINE(q'~    if (v.ram === 'Y') flags.push('over the host memory share');~');
  DBMS_OUTPUT.PUT_LINE(q'~    if (v.sga === 'Y') flags.push('does not fit in sga_target');~');
  DBMS_OUTPUT.PUT_LINE(q'~    return '<div class="mrow ' + gradeTone(v) + '"><div class="mh"><span class="ma">' + esc(v.al || v.area) + '</span>' +~');
  DBMS_OUTPUT.PUT_LINE(q'~      '<span class="gp ' + gradeTone(v) + '">' + esc(gradeName(v.g)) + '</span><span class="msz">' + sz + '</span></div>' +~');
  DBMS_OUTPUT.PUT_LINE(q'~      (v.hl ? '<p class="mhl">' + esc(v.hl) + '</p>' : '') + (v.why ? '<p class="mwhy">' + esc(v.why) + '</p>' : '') +~');
  DBMS_OUTPUT.PUT_LINE(q'~      (flags.length ? '<div class="mflags">' + flags.map(function (f) { return '<span class="tag mflag">' + esc(f) + '</span>'; }).join('') + '</div>' : '') +~');
  DBMS_OUTPUT.PUT_LINE(q'~      memEvidenceHtml(v) + '</div>';~');
  DBMS_OUTPUT.PUT_LINE(q'~  }~');
  DBMS_OUTPUT.PUT_LINE(NULL);
  DBMS_OUTPUT.PUT_LINE(q'~  function memCardHtml(c) {~');
  DBMS_OUTPUT.PUT_LINE(q'~    var w0 = null, w1 = null, nd = null, mode = null;~');
  DBMS_OUTPUT.PUT_LINE(q'~    c.vs.forEach(function (v) {~');
  DBMS_OUTPUT.PUT_LINE(q'~      if (v.w0 && (w0 == null || dayN(v.w0) < w0)) w0 = dayN(v.w0);~');
  DBMS_OUTPUT.PUT_LINE(q'~      if (v.w1 && (w1 == null || dayN(v.w1) > w1)) w1 = dayN(v.w1);~');
  DBMS_OUTPUT.PUT_LINE(q'~      if (v.nd != null) nd = Math.max(nd || 0, v.nd);~');
  DBMS_OUTPUT.PUT_LINE(q'~      mode = mode || v.mode;~');
  DBMS_OUTPUT.PUT_LINE(q'~    });~');
  DBMS_OUTPUT.PUT_LINE(q'~    var multi = memInstances[c.v.dbid].length > 1;~');
  DBMS_OUTPUT.PUT_LINE(q'~    var o = ['<article class="card mem" id="' + c.id + '"><div class="ch"><h3>' + esc(conLabel(c.v.dbid, c.v.con)) + '</h3>' +~');
  DBMS_OUTPUT.PUT_LINE(q'~      (multi ? '<span class="ctr">instance ' + esc(c.v.inst) + '</span>' : '') + (mode ? '<span class="tag">' + esc(mode) + '</span>' : '') +~');
  DBMS_OUTPUT.PUT_LINE(q'~      (w1 != null ? '<span class="mwin">evidence ' + (w0 != null ? fDay(w0) + ' \u2013 ' : '') + fDayY(w1) + (nd != null ? ' \u00b7 ' + nd + ' sampled day' + (nd === 1 ? '' : 's') : '') + '</span>' : '') +~');
  DBMS_OUTPUT.PUT_LINE(q'~      '</div><div class="mbody"><div class="mvs">' + c.vs.map(memRowHtml).join('') + '</div><div class="mside">'];~');
  DBMS_OUTPUT.PUT_LINE(q'~    var st = c.pts.length ? memStack(c.pts) : null;~');
  DBMS_OUTPUT.PUT_LINE(q'~    if (st && st.days.length) {~');
  DBMS_OUTPUT.PUT_LINE(q'~      var id = MCHARTS.length;~');
  DBMS_OUTPUT.PUT_LINE(q'~      o.push('<h4>SGA components by day</h4><div class="mchart" data-mchart="' + id + '">' + memChartSvg(st, id) + '<div class="tip"></div></div>' + memLegendHtml(st));~');
  DBMS_OUTPUT.PUT_LINE(q'~    } else {~');
  DBMS_OUTPUT.PUT_LINE(q'~      o.push('<p class="mnone">No SGA component history in the window.</p>');~');
  DBMS_OUTPUT.PUT_LINE(q'~    }~');
  DBMS_OUTPUT.PUT_LINE(q'~    o.push('</div></div></article>');~');
  DBMS_OUTPUT.PUT_LINE(q'~    return o.join('');~');
  DBMS_OUTPUT.PUT_LINE(q'~  }~');
  DBMS_OUTPUT.PUT_LINE(NULL);
  DBMS_OUTPUT.PUT_LINE(q'~  function memActions() {~');
  DBMS_OUTPUT.PUT_LINE(q'~    var acts = [];~');
  DBMS_OUTPUT.PUT_LINE(q'~    memCards.forEach(function (c) { c.vs.forEach(function (v) { if (v.act === 'Y') acts.push({ c: c, v: v }); }); });~');
  DBMS_OUTPUT.PUT_LINE(q'~    return acts.sort(function (a, b) {~');
  DBMS_OUTPUT.PUT_LINE(q'~      var ga = GRADE_ORDER[a.v.g] != null ? GRADE_ORDER[a.v.g] : 3, gb = GRADE_ORDER[b.v.g] != null ? GRADE_ORDER[b.v.g] : 3;~');
  DBMS_OUTPUT.PUT_LINE(q'~      return ga - gb || a.v.ar - b.v.ar;~');
  DBMS_OUTPUT.PUT_LINE(q'~    });~');
  DBMS_OUTPUT.PUT_LINE(q'~  }~');
  DBMS_OUTPUT.PUT_LINE(NULL);
  DBMS_OUTPUT.PUT_LINE(q'~  function memSummary() {~');
  DBMS_OUTPUT.PUT_LINE(q'~    var n = memActions().length;~');
  DBMS_OUTPUT.PUT_LINE(q'~    return '<span><b>' + memCards.length + '</b> instance' + (memCards.length === 1 ? '' : 's') + '</span>' +~');
  DBMS_OUTPUT.PUT_LINE(q'~      '<span>' + (n ? '<b>' + n + '</b> change' + (n === 1 ? '' : 's') + ' advised' : 'no change advised') + '</span>' +~');
  DBMS_OUTPUT.PUT_LINE(q'~      '<span>advice only, not counted as alerts</span>';~');
  DBMS_OUTPUT.PUT_LINE(q'~  }~');
