  DBMS_OUTPUT.PUT_LINE(q'~      (acts.length > 1 ? ' \u00b7 ' + (acts.length - 1) + ' more change' + (acts.length > 2 ? 's' : '') + ' advised' : '');~');
  DBMS_OUTPUT.PUT_LINE(q'~  }~');
