  DBMS_OUTPUT.PUT_LINE(q'~    return '<svg viewBox="0 0 240 28" preserveAspectRatio="xMinYMid meet" aria-hidden="true">' + vs.map(function (v, i) {~');
  DBMS_OUTPUT.PUT_LINE(q'~      var t = gradeTone(v), x = (i * (cw + 3) + 0.5).toFixed(1);~');
  DBMS_OUTPUT.PUT_LINE(q'~      return '<rect x="' + x + '" y="8.5" width="' + cw.toFixed(1) + '" height="11" rx="1.5" fill="' + (t === 'act' ? 'var(--accent)' : 'var(--surface)') + '"' +~');
  DBMS_OUTPUT.PUT_LINE(q'~        (t === 'act' ? '' : ' stroke="var(--line)"' + (t === 'ie' ? ' stroke-dasharray="2 2"' : '')) + '/>';~');
  DBMS_OUTPUT.PUT_LINE(q'~    }).join('') + '</svg>';~');
  DBMS_OUTPUT.PUT_LINE(q'~  }~');
  DBMS_OUTPUT.PUT_LINE(NULL);
  DBMS_OUTPUT.PUT_LINE(q'~  /* ---------- tablespace families: one tablespace per period, judged as a group ---------- */~');
