  DBMS_OUTPUT.PUT_LINE(q'~      '<span class="ctr">' + esc(conLabel(f.dbid, f.con)) + '</span>' + (PERIOD_LABEL[f.per] ? '<span class="tag">' + PERIOD_LABEL[f.per] + '</span>' : '') +~');
