  DBMS_OUTPUT.PUT_LINE(q'~  html.push('<div class="page"><header class="mast"><span><b>' + esc(dbName) + '</b>' + esc(M.host || '') +~');
  DBMS_OUTPUT.PUT_LINE(q'~    (nCon > 1 ? ', ' + nCon + ' containers' : '') + (FIRST != null ? ', data ' + fDayY(FIRST) + ' \u2013 ' + fDayY(LAST) + ' (' + (LAST - FIRST + 1) + ' d)' : '') +~');
