  DBMS_OUTPUT.PUT_LINE(q'~  function nearest(pts, x) {~');
  DBMS_OUTPUT.PUT_LINE(q'~    var best = null, bd = Infinity;~');
  DBMS_OUTPUT.PUT_LINE(q'~    pts.forEach(function (p) { if (p.y != null && Math.abs(p.x - x) < bd) { bd = Math.abs(p.x - x); best = p; } });~');
  DBMS_OUTPUT.PUT_LINE(q'~    return best;~');
  DBMS_OUTPUT.PUT_LINE(q'~  }~');
  DBMS_OUTPUT.PUT_LINE(q'~  function anomalyNote(m, s, day) {~');
  DBMS_OUTPUT.PUT_LINE(q'~    var hit = m.anoms.filter(function (a) { return a.s === s && dayN(a.ts) === day && a.ak !== 'CPU_SHIFT'; });~');
  DBMS_OUTPUT.PUT_LINE(q'~    if (!hit.length) return '';~');
  DBMS_OUTPUT.PUT_LINE(q'~    var z = hit.reduce(function (b, a) { return Math.abs(a.z) > Math.abs(b.z) ? a : b; });~');
  DBMS_OUTPUT.PUT_LINE(q'~    if (m.fam.id === 'tablespaces') return 'unusual growth ' + sign(z.v) + fBytes(Math.abs(z.v)) + ', usual ' + fBytes(z.e) + ' \u00b7 z ' + num(z.z, 1);~');
  DBMS_OUTPUT.PUT_LINE(q'~    return 'unusual, usual ' + m.unit.fmt(z.e) + ' \u00b7 z ' + num(z.z, 1);~');
  DBMS_OUTPUT.PUT_LINE(q'~  }~');
  DBMS_OUTPUT.PUT_LINE(NULL);
  DBMS_OUTPUT.PUT_LINE(q'~  Array.prototype.forEach.call(document.querySelectorAll('.chart'), function (el) {~');
  DBMS_OUTPUT.PUT_LINE(q'~    var spec = CHARTS[+el.getAttribute('data-chart')];~');
  DBMS_OUTPUT.PUT_LINE(q'~    var svg = el.querySelector('svg'), tip = el.querySelector('.tip');~');
  DBMS_OUTPUT.PUT_LINE(q'~    var hx = svg.querySelector('.hx'), hd = svg.querySelector('.hd'), hit = svg.querySelector('.hit');~');
  DBMS_OUTPUT.PUT_LINE(q'~    function hide() { tip.classList.remove('on'); hx.setAttribute('visibility', 'hidden'); hd.setAttribute('visibility', 'hidden'); }~');
  DBMS_OUTPUT.PUT_LINE(q'~    hit.addEventListener('mouseleave', hide);~');
  DBMS_OUTPUT.PUT_LINE(q'~    hit.addEventListener('mousemove', function (ev) {~');
  DBMS_OUTPUT.PUT_LINE(q'~      var r = svg.getBoundingClientRect();~');
  DBMS_OUTPUT.PUT_LINE(q'~      var vx = (ev.clientX - r.left) / r.width * W;~');
  DBMS_OUTPUT.PUT_LINE(q'~      var x = spec.x0 + (vx - ML) / (W - ML - MR) * (spec.x1 - spec.x0);~');
  DBMS_OUTPUT.PUT_LINE(q'~      var lines = [], px, py;~');
  DBMS_OUTPUT.PUT_LINE(q'~      if (x <= LAST + 0.5) {~');
  DBMS_OUTPUT.PUT_LINE(q'~        var p = nearest(spec.lines[0].pts, x);~');
  DBMS_OUTPUT.PUT_LINE(q'~        if (!p) return hide();~');
  DBMS_OUTPUT.PUT_LINE(q'~        px = spec.xs(p.x); py = spec.ys(p.y);~');
  DBMS_OUTPUT.PUT_LINE(q'~        lines.push('<b>' + fWDay(p.x) + ' ' + dateOf(p.x).getUTCFullYear() + '</b>');~');
  DBMS_OUTPUT.PUT_LINE(q'~        spec.lines.forEach(function (l) {~');
  DBMS_OUTPUT.PUT_LINE(q'~          var q = nearest(l.pts, p.x);~');
  DBMS_OUTPUT.PUT_LINE(q'~          if (q && q.x === p.x) lines.push((l.label ? esc(l.label) + ' ' : '') + '<b>' + spec.unit.fmt(q.y) + '</b>' + (spec.m.f.lim && l.role === 0 && !spec.pctAxis ? ' \u00b7 ' + num(q.y / (q.lim || spec.m.f.lim) * 100, 1) + '%' : ''));~');
  DBMS_OUTPUT.PUT_LINE(q'~          if (q && q.x === p.x && (q.a === 1 || q.a === -1)) {~');
  DBMS_OUTPUT.PUT_LINE(q'~            var note = anomalyNote(spec.m, l.s, q.x);~');
  DBMS_OUTPUT.PUT_LINE(q'~            lines.push('<span class="a">' + esc(note || 'unusual') + '</span>');~');
  DBMS_OUTPUT.PUT_LINE(q'~          }~');
  DBMS_OUTPUT.PUT_LINE(q'~        });~');
  DBMS_OUTPUT.PUT_LINE(q'~      } else {~');
  DBMS_OUTPUT.PUT_LINE(q'~        var fc = spec.fc;~');
  DBMS_OUTPUT.PUT_LINE(q'~        if (fc.length < 2) return hide();~');
  DBMS_OUTPUT.PUT_LINE(q'~        var i = 1;~');
  DBMS_OUTPUT.PUT_LINE(q'~        while (i < fc.length - 1 && fc[i].x < x) i++;~');
  DBMS_OUTPUT.PUT_LINE(q'~        var a = fc[i - 1], b = fc[i], t = Math.max(0, Math.min(1, (x - a.x) / (b.x - a.x)));~');
  DBMS_OUTPUT.PUT_LINE(q'~        var xd = Math.round(a.x + t * (b.x - a.x));~');
  DBMS_OUTPUT.PUT_LINE(q'~        t = (xd - a.x) / (b.x - a.x);~');
  DBMS_OUTPUT.PUT_LINE(q'~        var y = a.y + t * (b.y - a.y);~');
  DBMS_OUTPUT.PUT_LINE(q'~        var lo = a.lo != null ? a.lo + t * ((b.lo != null ? b.lo : b.y) - a.lo) : (b.lo != null ? a.y + t * (b.lo - a.y) : null);~');
  DBMS_OUTPUT.PUT_LINE(q'~        var hi = a.hi != null ? a.hi + t * ((b.hi != null ? b.hi : b.y) - a.hi) : (b.hi != null ? a.y + t * (b.hi - a.y) : null);~');
  DBMS_OUTPUT.PUT_LINE(q'~        px = spec.xs(xd); py = spec.ys(y);~');
  DBMS_OUTPUT.PUT_LINE(q'~        lines.push('<b>' + fWDay(xd) + ' ' + dateOf(xd).getUTCFullYear() + '</b> \u00b7 +' + (xd - LAST) + ' d');~');
  DBMS_OUTPUT.PUT_LINE(q'~        lines.push('forecast <b>' + spec.unit.fmt(y) + '</b>');~');
  DBMS_OUTPUT.PUT_LINE(q'~        if (lo != null && hi != null) lines.push('95% ' + spec.unit.fmt(lo) + ' \u2013 ' + spec.unit.fmt(hi));~');
  DBMS_OUTPUT.PUT_LINE(q'~      }~');
  DBMS_OUTPUT.PUT_LINE(q'~      hx.setAttribute('x1', px); hx.setAttribute('x2', px); hx.setAttribute('visibility', 'visible');~');
  DBMS_OUTPUT.PUT_LINE(q'~      hd.setAttribute('cx', px); hd.setAttribute('cy', py); hd.setAttribute('visibility', 'visible');~');
  DBMS_OUTPUT.PUT_LINE(q'~      tip.innerHTML = lines.join('<br>');~');
  DBMS_OUTPUT.PUT_LINE(q'~      tip.style.left = Math.max(70, Math.min(r.width - 70, px / W * r.width)) + 'px';~');
  DBMS_OUTPUT.PUT_LINE(q'~      tip.style.top = (py / H * r.height) + 'px';~');
  DBMS_OUTPUT.PUT_LINE(q'~      tip.classList.add('on');~');
  DBMS_OUTPUT.PUT_LINE(q'~    });~');
  DBMS_OUTPUT.PUT_LINE(q'~  });~');
  DBMS_OUTPUT.PUT_LINE(NULL);
  DBMS_OUTPUT.PUT_LINE(q'~  Array.prototype.forEach.call(document.querySelectorAll('.mchart'), function (el) {~');
  DBMS_OUTPUT.PUT_LINE(q'~    var spec = MCHARTS[+el.getAttribute('data-mchart')];~');
  DBMS_OUTPUT.PUT_LINE(q'~    var svg = el.querySelector('svg'), tip = el.querySelector('.tip');~');
  DBMS_OUTPUT.PUT_LINE(q'~    var hx = svg.querySelector('.hx'), hit = svg.querySelector('.hit');~');
  DBMS_OUTPUT.PUT_LINE(q'~    function hide() { tip.classList.remove('on'); hx.setAttribute('visibility', 'hidden'); }~');
  DBMS_OUTPUT.PUT_LINE(q'~    hit.addEventListener('mouseleave', hide);~');
  DBMS_OUTPUT.PUT_LINE(q'~    hit.addEventListener('mousemove', function (ev) {~');
  DBMS_OUTPUT.PUT_LINE(q'~      var r = svg.getBoundingClientRect();~');
  DBMS_OUTPUT.PUT_LINE(q'~      var x = spec.x0 + ((ev.clientX - r.left) / r.width * MW - MML) / (MW - MML - MMR) * (spec.x1 - spec.x0);~');
  DBMS_OUTPUT.PUT_LINE(q'~      var d = spec.st.days.reduce(function (b, k) { return Math.abs(k - x) < Math.abs(b - x) ? k : b; });~');
  DBMS_OUTPUT.PUT_LINE(q'~      var lines = ['<b>' + fWDay(d) + ' ' + dateOf(d).getUTCFullYear() + '</b>'], tot = 0;~');
  DBMS_OUTPUT.PUT_LINE(q'~      spec.st.comps.slice().reverse().forEach(function (c) {~');
  DBMS_OUTPUT.PUT_LINE(q'~        var p = c.byX[d];~');
  DBMS_OUTPUT.PUT_LINE(q'~        if (!p) return;~');
  DBMS_OUTPUT.PUT_LINE(q'~        tot += p.b;~');
  DBMS_OUTPUT.PUT_LINE(q'~        lines.push(esc(c.c) + ' <b>' + memSize(p.b) + '</b>' + (memMoved(c, d) ? ' <span class="m">' + memRange(p.lo, p.hi) + ' \u00b7 ' + p.ops + ' op' + (p.ops === 1 ? '' : 's') + '</span>' : ''));~');
  DBMS_OUTPUT.PUT_LINE(q'~      });~');
  DBMS_OUTPUT.PUT_LINE(q'~      lines.push('total <b>' + memSize(tot) + '</b>');~');
  DBMS_OUTPUT.PUT_LINE(q'~      var px = spec.xs(d);~');
  DBMS_OUTPUT.PUT_LINE(q'~      hx.setAttribute('x1', px); hx.setAttribute('x2', px); hx.setAttribute('visibility', 'visible');~');
  DBMS_OUTPUT.PUT_LINE(q'~      tip.innerHTML = lines.join('<br>');~');
  DBMS_OUTPUT.PUT_LINE(q'~      tip.style.left = Math.max(90, Math.min(r.width - 90, px / MW * r.width)) + 'px';~');
  DBMS_OUTPUT.PUT_LINE(q'~      tip.style.top = (MMT / MH * r.height) + 'px';~');
  DBMS_OUTPUT.PUT_LINE(q'~      tip.classList.add('on');~');
  DBMS_OUTPUT.PUT_LINE(q'~    });~');
  DBMS_OUTPUT.PUT_LINE(q'~  });~');
  DBMS_OUTPUT.PUT_LINE(NULL);
  DBMS_OUTPUT.PUT_LINE(q'~  /* Print the memory evidence open, then close what the reader had closed. */~');
  DBMS_OUTPUT.PUT_LINE(q'~  if (window.addEventListener) {~');
  DBMS_OUTPUT.PUT_LINE(q'~    var closed = [];~');
  DBMS_OUTPUT.PUT_LINE(q'~    window.addEventListener('beforeprint', function () {~');
  DBMS_OUTPUT.PUT_LINE(q'~      closed = Array.prototype.filter.call(document.querySelectorAll('details.mev'), function (el) { return !el.open; });~');
  DBMS_OUTPUT.PUT_LINE(q'~      closed.forEach(function (el) { el.open = true; });~');
  DBMS_OUTPUT.PUT_LINE(q'~    });~');
  DBMS_OUTPUT.PUT_LINE(q'~    window.addEventListener('afterprint', function () { closed.forEach(function (el) { el.open = false; }); });~');
  DBMS_OUTPUT.PUT_LINE(q'~  }~');
  DBMS_OUTPUT.PUT_LINE(NULL);
  DBMS_OUTPUT.PUT_LINE(q'~  Array.prototype.forEach.call(document.querySelectorAll('.heat'), function (el) {~');
  DBMS_OUTPUT.PUT_LINE(q'~    var tip = document.createElement('div');~');
  DBMS_OUTPUT.PUT_LINE(q'~    tip.className = 'tip';~');
  DBMS_OUTPUT.PUT_LINE(q'~    el.style.position = 'relative';~');
  DBMS_OUTPUT.PUT_LINE(q'~    el.appendChild(tip);~');
  DBMS_OUTPUT.PUT_LINE(q'~    el.addEventListener('mousemove', function (ev) {~');
  DBMS_OUTPUT.PUT_LINE(q'~      var c = ev.target;~');
  DBMS_OUTPUT.PUT_LINE(q'~      if (!c.classList || !c.classList.contains('hc')) { tip.classList.remove('on'); return; }~');
  DBMS_OUTPUT.PUT_LINE(q'~      var r = el.getBoundingClientRect(), cr = c.getBoundingClientRect();~');
  DBMS_OUTPUT.PUT_LINE(q'~      var v = c.getAttribute('data-v'), f = +c.getAttribute('data-f'), h = +c.getAttribute('data-h');~');
  DBMS_OUTPUT.PUT_LINE(q'~      tip.innerHTML = '<b>' + fWDay(+c.getAttribute('data-d')) + ' ' + (h < 10 ? '0' : '') + h + ':00</b> ' + (v === '' ? 'no data' : num(+v, 1) + '%') +~');
  DBMS_OUTPUT.PUT_LINE(q'~        (f === 1 ? '<br><span class="a">busier than this hour usually is</span>' : f === -1 ? '<br><span class="a">quieter than this hour usually is</span>' : '');~');
  DBMS_OUTPUT.PUT_LINE(q'~      tip.style.left = (cr.left - r.left + cr.width / 2) + 'px';~');
  DBMS_OUTPUT.PUT_LINE(q'~      tip.style.top = (cr.top - r.top) + 'px';~');
  DBMS_OUTPUT.PUT_LINE(q'~      tip.classList.add('on');~');
  DBMS_OUTPUT.PUT_LINE(q'~    });~');
  DBMS_OUTPUT.PUT_LINE(q'~    el.addEventListener('mouseleave', function () { tip.classList.remove('on'); });~');
  DBMS_OUTPUT.PUT_LINE(q'~  });~');
  DBMS_OUTPUT.PUT_LINE(NULL);
  DBMS_OUTPUT.PUT_LINE(q'~  var root = document.documentElement, TK = 'cap-theme';~');
  DBMS_OUTPUT.PUT_LINE(q'~  try { var saved = localStorage.getItem(TK); if (saved) root.setAttribute('data-theme', saved); } catch (e) { /* storage blocked */ }~');
  DBMS_OUTPUT.PUT_LINE(q'~  document.getElementById('themeBtn').onclick = function () {~');
  DBMS_OUTPUT.PUT_LINE(q'~    var cur = root.getAttribute('data-theme');~');
  DBMS_OUTPUT.PUT_LINE(q'~    var dark = cur ? cur === 'dark' : window.matchMedia('(prefers-color-scheme: dark)').matches;~');
  DBMS_OUTPUT.PUT_LINE(q'~    var next = dark ? 'light' : 'dark';~');
  DBMS_OUTPUT.PUT_LINE(q'~    root.setAttribute('data-theme', next);~');
  DBMS_OUTPUT.PUT_LINE(q'~    try { localStorage.setItem(TK, next); } catch (e) { /* storage blocked */ }~');
  DBMS_OUTPUT.PUT_LINE(q'~  };~');
  DBMS_OUTPUT.PUT_LINE(NULL);
  DBMS_OUTPUT.PUT_LINE(q'~  if ('IntersectionObserver' in window) {~');
  DBMS_OUTPUT.PUT_LINE(q'~    var links = {};~');
  DBMS_OUTPUT.PUT_LINE(q'~    Array.prototype.forEach.call(document.querySelectorAll('.nav a'), function (a) { links[a.getAttribute('href').slice(1)] = a; });~');
  DBMS_OUTPUT.PUT_LINE(q'~    var io = new IntersectionObserver(function (entries) {~');
  DBMS_OUTPUT.PUT_LINE(q'~      entries.forEach(function (e) {~');
  DBMS_OUTPUT.PUT_LINE(q'~        if (e.isIntersecting && links[e.target.id]) {~');
  DBMS_OUTPUT.PUT_LINE(q'~          Object.keys(links).forEach(function (k) { links[k].classList.toggle('on', k === e.target.id); });~');
  DBMS_OUTPUT.PUT_LINE(q'~        }~');
  DBMS_OUTPUT.PUT_LINE(q'~      });~');
  DBMS_OUTPUT.PUT_LINE(q'~    }, { rootMargin: '-60px 0px -70% 0px' });~');
  DBMS_OUTPUT.PUT_LINE(q'~    Array.prototype.forEach.call(document.querySelectorAll('main section'), function (s) { io.observe(s); });~');
  DBMS_OUTPUT.PUT_LINE(q'~  }~');
  DBMS_OUTPUT.PUT_LINE(q'~})();~');
  DBMS_OUTPUT.PUT_LINE(q'~</script>~');
  DBMS_OUTPUT.PUT_LINE(q'~</body>~');
  DBMS_OUTPUT.PUT_LINE(q'~</html>~');
END;
/
